screenPanels.initJs:
function(container, apiUrl, tables) {
  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  // パスワード表示/非表示切り替え
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const passwordInput = container.querySelector('#password');

  togglePasswordBtn.addEventListener('click', () => {
    if (passwordInput.type === 'password') {
      passwordInput.type = 'text';
      togglePasswordBtn.textContent = '🙈';
    } else {
      passwordInput.type = 'password';
      togglePasswordBtn.textContent = '👁';
    }
  });

  // ログインボタンホバー効果
  const loginBtn = container.querySelector('#btn-login');
  loginBtn.addEventListener('mouseenter', () => {
    loginBtn.style.background = 'var(--primary-hover)';
  });
  loginBtn.addEventListener('mouseleave', () => {
    loginBtn.style.background = 'var(--primary)';
  });

  // フォーカス時のスタイル適用
  const inputs = container.querySelectorAll('input[type="text"], input[type="password"]');
  inputs.forEach(input => {
    input.addEventListener('focus', () => {
      input.style.outline = 'none';
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });
    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });
  });

  // ログインフォーム送信処理
  const loginForm = container.querySelector('#login-form');
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    const userId = container.querySelector('#user-id').value.trim();
    const password = container.querySelector('#password').value;
    const rememberMe = container.querySelector('#remember-me').checked;

    if (!userId || !password) {
      showError('ユーザーIDとパスワードを入力してください。');
      return;
    }

    // ログインボタンを無効化
    loginBtn.disabled = true;
    loginBtn.textContent = 'ログイン中...';

    try {
      // ユーザーテーブル（tables[0]）からユーザー情報を取得
      const users = await window.aivicApi.list(0);

      if (!users) {
        showError('システムエラーが発生しました。管理者にお問い合わせください。');
        return;
      }

      // ユーザー認証（実際の実装では暗号化されたパスワードと比較）
      const user = users.find(u => 
        u.ユーザー名 === userId && 
        u.有効フラグ === true
      );

      if (!user) {
        showError('ユーザーIDまたはパスワードが正しくありません。');
        return;
      }

      // 簡易パスワードチェック（実際の実装ではハッシュ比較）
      if (password !== 'password123') {
        showError('ユーザーIDまたはパスワードが正しくありません。');
        return;
      }

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態保持の処理
      if (rememberMe) {
        localStorage.setItem('rememberedUser', userId);
      } else {
        localStorage.removeItem('rememberedUser');
      }

      // セッション情報を保存
      sessionStorage.setItem('currentUser', JSON.stringify({
        userId: user.ユーザーID,
        userName: user.ユーザー名,
        fullName: user.氏名,
        department: user.所属部署,
        role: user.権限レベル
      }));

      // ログイン成功 - 工数記録画面へ遷移
      window.showScreen("scr-1778907133295");

    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました。');
    } finally {
      // ログインボタンを再有効化
      loginBtn.disabled = false;
      loginBtn.textContent = 'ログイン';
    }
  });

  // パスワードを忘れた場合のリンク
  const forgotPasswordLink = container.querySelector('#forgot-password-link');
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    alert('パスワードリセット機能は管理者にお問い合わせください。\n連絡先: admin@company.com');
  });

  // 記憶されたユーザーIDがあれば自動入力
  const rememberedUser = localStorage.getItem('rememberedUser');
  if (rememberedUser) {
    container.querySelector('#user-id').value = rememberedUser;
    container.querySelector('#remember-me').checked = true;
    container.querySelector('#password').focus();
  } else {
    container.querySelector('#user-id').focus();
  }

  // Enterキーでのフォーム送信
  container.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && (e.target.id === 'user-id' || e.target.id === 'password')) {
      loginForm.dispatchEvent(new Event('submit'));
    }
  });
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let timerInterval = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;

  // 現在日時更新
  function updateCurrentTime() {
    const now = new Date();
    container.querySelector('#current-datetime').textContent = 
      now.toLocaleDateString('ja-JP') + ' ' + now.toLocaleTimeString('ja-JP');
  }
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);

  // 作業項目選択肢を設定
  function loadWorkItems() {
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    if (workItemsTable) {
      const select = container.querySelector('#work-item-select');
      select.innerHTML = '<option value="">選択してください</option>';
      workItemsTable.records.forEach(item => {
        if (item.有効フラグ) {
          select.innerHTML += `<option value="${item.作業項目ID}">${item.作業項目名}</option>`;
        }
      });
    }
  }

  // 経過時間表示更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;
    if (pauseStartTime) {
      elapsed -= (now - pauseStartTime);
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    container.querySelector('#elapsed-time').textContent = 
      `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  }

  // 本日の作業履歴を描画
  function renderTodayWorkList(records) {
    const tbody = container.querySelector('#today-work-list');
    const today = new Date().toDateString();
    const todayRecords = records.filter(r => new Date(r.作業日).toDateString() === today);

    tbody.innerHTML = todayRecords.map(record => {
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}h${record.作業時間 % 60}m` : '';

      return `
        <tr data-id="${record.作業記録ID}">
          <td>${startTime}</td>
          <td>${endTime}</td>
          <td>${workTime}</td>
          <td>${record.作業種別 || ''}</td>
          <td>${record.作業場所 || ''}</td>
          <td>
            <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; 
              ${record.進捗状況 === '作業中' ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 
                record.進捗状況 === '完了' ? 'background: rgba(59, 130, 246, 0.2); color: #3b82f6;' : 
                'background: rgba(239, 68, 68, 0.2); color: #ef4444;'}">
              ${record.進捗状況 || ''}
            </span>
          </td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 2px 6px; margin-right: 4px;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 2px 6px;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ読み込み
  loadWorkItems();
  const workRecordsTableIndex = tables.findIndex(t => t.tableName === '作業記録');
  if (workRecordsTableIndex >= 0) {
    renderTodayWorkList(tables[workRecordsTableIndex].records || []);

    // 最新データを取得
    window.aivicApi.list(workRecordsTableIndex).then(records => {
      if (records) renderTodayWorkList(records);
    });
  }

  // 作業開始
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location').value;

    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }
    if (!workLocation) {
      alert('作業場所を入力してください');
      return;
    }

    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    const selectedItem = workItemsTable.records.find(item => item.作業項目ID === workItemId);

    const newRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証済みユーザーIDを使用
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      プロジェクト名: selectedItem?.作業項目名|| '',
      作業場所: workLocation,
      作業種別: selectedItem?.作業項目名|| '',
      作業内容: '',
      進捗状況: '作業中',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(workRecordsTableIndex, newRecord);
    if (saved) {
      currentWorkRecord = saved;
      startTime = new Date();
      totalPauseTime = 0;
      pauseStartTime = null;

      // ボタン状態更新
      container.querySelector('#btn-start-work').disabled = true;
      container.querySelector('#btn-end-work').disabled = false;
      container.querySelector('#btn-pause-work').disabled = false;

      // タイマー開始
      timerInterval = setInterval(updateElapsedTime, 1000);

      // 履歴更新
      const records = await window.aivicApi.list(workRecordsTableIndex);
      if (records) renderTodayWorkList(records);
    }
  });

  // 作業終了
  container.querySelector('#btn-end-work').addEventListener('click', async () => {
    if (!currentWorkRecord) return;

    const workMemo = container.querySelector('#work-memo').value;
    const endTime = new Date();
    const workTimeMinutes = Math.floor((endTime - startTime - totalPauseTime) / (1000 * 60));

    const updated = await window.aivicApi.update(workRecordsTableIndex, currentWorkRecord.作業記録ID || currentWorkRecord.id, {
      作業終了時刻: endTime.toISOString(),
      作業時間: workTimeMinutes,
      作業内容: workMemo,
      進捗状況: '完了'
    });

    if (updated) {
      // 状態リセット
      currentWorkRecord = null;
      startTime = null;
      totalPauseTime = 0;
      pauseStartTime = null;
      clearInterval(timerInterval);

      // ボタン状態更新
      container.querySelector('#btn-start-work').disabled = false;
      container.querySelector('#btn-end-work').disabled = true;
      container.querySelector('#btn-pause-work').disabled = true;
      container.querySelector('#elapsed-time').textContent = '00:00:00';

      // フォームクリア
      container.querySelector('#work-item-select').value = '';
      container.querySelector('#work-location').value = '';
      container.querySelector('#work-memo').value = '';

      // 履歴更新
      const records = await window.aivicApi.list(workRecordsTableIndex);
      if (records) renderTodayWorkList(records);
    }
  });

  // 作業中断
  container.querySelector('#btn-pause-work').addEventListener('click', () => {
    pauseStartTime = new Date();
    container.querySelector('#pause-reason-area').style.display = 'block';
    container.querySelector('#btn-pause-work').disabled = true;
  });

  // 作業再開
  container.querySelector('#btn-resume-work').addEventListener('click', async () => {
    const reasonCategory = container.querySelector('#pause-reason-category').value;
    const reasonDetail = container.querySelector('#pause-reason-detail').value;

    if (!reasonCategory) {
      alert('中断理由区分を選択してください');
      return;
    }

    if (pauseStartTime) {
      const pauseEndTime = new Date();
      const pauseDuration = pauseEndTime - pauseStartTime;
      totalPauseTime += pauseDuration;

      // 中断記録を保存
      const pauseRecordsTableIndex = tables.findIndex(t => t.tableName === '中断記録');
      if (pauseRecordsTableIndex >= 0) {
        await window.aivicApi.save(pauseRecordsTableIndex, {
          作業記録ID: currentWorkRecord.作業記録ID || currentWorkRecord.id,
          中断開始日時: pauseStartTime.toISOString(),
          中断終了日時: pauseEndTime.toISOString(),
          中断理由区分: reasonCategory,
          中断理由詳細: reasonDetail,
          中断時間: Math.floor(pauseDuration / (1000 * 60)),
          対応状況: '解決済み',
          記録者ID: 'current-user-id'
        });
      }
    }

    pauseStartTime = null;
    container.querySelector('#pause-reason-area').style.display = 'none';
    container.querySelector('#btn-pause-work').disabled = false;
    container.querySelector('#pause-reason-category').value = '';
    container.querySelector('#pause-reason-detail').value = '';
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#work-memo').value = '';
  });

  // 保存ボタン（作業中の内容更新）
  container.querySelector('#btn-save-work').addEventListener('click', async () => {
    if (!currentWorkRecord) {
      alert('作業が開始されていません');
      return;
    }

    const workMemo = container.querySelector('#work-memo').value;
    const updated = await window.aivicApi.update(workRecordsTableIndex, currentWorkRecord.作業記録ID || currentWorkRecord.id, {
      作業内容: workMemo
    });

    if (updated) {
      alert('作業内容を保存しました');
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この作業記録を削除しますか？')) return;

      await window.aivicApi.delete(workRecordsTableIndex, deleteBtn.dataset.id);
      const records = await window.aivicApi.list(workRecordsTableIndex);
      if (records) renderTodayWorkList(records);
      return;
    }

    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      // 編集機能は簡略化（実際の実装では編集フォームを表示）
      alert('編集機能は作業履歴画面で行ってください');
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#history-tbody");
  const recordCount = container.querySelector("#record-count");

  // 中断回数を計算する関数
  function getInterruptionCount(workRecordId, interruptionRecords) {
    return interruptionRecords.filter(interrupt => interrupt.作業記録ID === workRecordId).length;
  }

  // 時間フォーマット関数
  function formatTime(dateTimeStr) {
    if (!dateTimeStr) return "-";
    const date = new Date(dateTimeStr);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 作業時間フォーマット関数
  function formatWorkTime(minutes) {
    if (!minutes) return "-";
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}h${mins.toString().padStart(2, '0')}m`;
  }

  // 日付フォーマット関数
  function formatDate(dateTimeStr) {
    if (!dateTimeStr) return "-";
    const date = new Date(dateTimeStr);
    return date.toLocaleDateString('ja-JP');
  }

  // ステータスバッジ関数
  function getStatusBadge(status) {
    const colors = {
      '完了': 'background: rgba(34, 197, 94, 0.15); color: #22c55e; border: 1px solid rgba(34, 197, 94, 0.3);',
      '作業中': 'background: rgba(59, 130, 246, 0.15); color: #3b82f6; border: 1px solid rgba(59, 130, 246, 0.3);',
      '中断': 'background: rgba(239, 68, 68, 0.15); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3);'
    };
    const style = colors[status] || 'background: rgba(156, 163, 175, 0.15); color: #9ca3af; border: 1px solid rgba(156, 163, 175, 0.3);';
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${style}">${status}</span>`;
  }

  // テーブル再描画関数
  function renderRows(workRecords, interruptionRecords = []) {
    tbody.innerHTML = workRecords.map(record => {
      const interruptCount = getInterruptionCount(record.作業記録ID, interruptionRecords);
      return `
        <tr data-id="${record.作業記録ID}" style="border-bottom: 1px solid rgba(255,255,255,0.02); cursor: pointer;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDate(record.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.プロジェクト名 || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.作業種別 || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(record.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(record.作業終了時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: right;">${formatWorkTime(record.作業時間)}</td>
          <td style="padding: 6px 10px; text-align: center;">${getStatusBadge(record.進捗状況)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: right;">${interruptCount}回</td>
          <td style="padding: 6px 10px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 3px 8px;">詳細確認</button>
          </td>
        </tr>
      `;
    }).join("");

    recordCount.textContent = `${workRecords.length}件`;
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      const interruptionRecords = await window.aivicApi.list(2); // 中断記録テーブル
      renderRows(workRecords || [], interruptionRecords || []);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderRows(tables[1]?.records || [], tables[2]?.records || []);
    }
  }

  // 検索処理
  async function performSearch() {
    try {
      const startDate = container.querySelector("#filter-start-date").value;
      const endDate = container.querySelector("#filter-end-date").value;
      const status = container.querySelector("#filter-status").value;

      const workRecords = await window.aivicApi.list(1);
      const interruptionRecords = await window.aivicApi.list(2);

      let filteredRecords = workRecords || [];

      // 日付範囲フィルター
      if (startDate) {
        filteredRecords = filteredRecords.filter(record => {
          const workDate = new Date(record.作業日).toISOString().split('T')[0];
          return workDate >= startDate;
        });
      }

      if (endDate) {
        filteredRecords = filteredRecords.filter(record => {
          const workDate = new Date(record.作業日).toISOString().split('T')[0];
          return workDate <= endDate;
        });
      }

      // ステータスフィルター
      if (status) {
        filteredRecords = filteredRecords.filter(record => record.進捗状況 === status);
      }

      renderRows(filteredRecords, interruptionRecords || []);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  }

  // CSVエクスポート処理
  async function exportCSV() {
    try {
      const workRecords = await window.aivicApi.list(1);
      const interruptionRecords = await window.aivicApi.list(2);

      const headers = ['作業日', 'プロジェクト名', '作業種別', '開始時刻', '終了時刻', '作業時間', '進捗状況', '中断回数', '作業内容'];
      const csvData = [headers];

      workRecords.forEach(record => {
        const interruptCount = getInterruptionCount(record.作業記録ID, interruptionRecords);
        csvData.push([
          formatDate(record.作業日),
          record.プロジェクト名 || '',
          record.作業種別 || '',
          formatTime(record.作業開始時刻),
          formatTime(record.作業終了時刻),
          formatWorkTime(record.作業時間),
          record.進捗状況 || '',
          `${interruptCount}回`,
          record.作業内容 || ''
        ]);
      });

      const csvContent = '\uFEFF' + csvData.map(row => 
        row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
      ).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `作業履歴_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
    }
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", performSearch);

  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-status").value = "";
    loadInitialData();
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-data-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778907367889");
      return;
    }
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#log-table-body");
  const detailPanel = container.querySelector("#detail-panel");
  let currentLogId = null;
  let allLogs = [];

  // 重要度バッジのスタイル
  function getSeverityBadge(severity) {
    const colors = {
      '高': 'background: #dc2626; color: #fff;',
      '中': 'background: #f59e0b; color: #fff;',
      '低': 'background: #10b981; color: #fff;'
    };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${colors[severity] || 'background: var(--bg-main); color: var(--text);'}">${severity || ''}</span>`;
  }

  // 確認状況バッジのスタイル
  function getStatusBadge(status) {
    const colors = {
      '未確認': 'background: #ef4444; color: #fff;',
      '確認済み': 'background: #f59e0b; color: #fff;',
      '対応済み': 'background: #10b981; color: #fff;'
    };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${colors[status] || 'background: var(--bg-main); color: var(--text);'}">${status || ''}</span>`;
  }

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="border-bottom: 1px solid var(--border); cursor: pointer;" class="log-row">
        <td style="padding: 6px 10px; color: var(--text);">${r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP') : ''}</td>
        <td style="padding: 6px 10px; color: var(--text);">${r.作業員名 || ''}</td>
        <td style="padding: 6px 10px; color: var(--text);">${r.異常値種別 || ''}</td>
        <td style="padding: 6px 10px; color: var(--text);">${r.検出項目 || ''}</td>
        <td style="padding: 6px 10px; color: var(--text);">${r.検出値 || ''}</td>
        <td style="padding: 6px 10px; color: var(--text);">${r.閾値 || ''}</td>
        <td style="padding: 6px 10px;">${getSeverityBadge(r.重要度)}</td>
        <td style="padding: 6px 10px;">${getStatusBadge(r.確認状況)}</td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary detail-btn" data-id="${r.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データを即座に描画
  allLogs = tables[4]?.records || [];
  renderRows(allLogs);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dateStart = container.querySelector("#input-date-start").value;
    const dateEnd = container.querySelector("#input-date-end").value;
    const anomalyType = container.querySelector("#select-anomaly-type").value;
    const workerName = container.querySelector("#input-worker-name").value;
    const severity = container.querySelector("#select-severity").value;
    const status = container.querySelector("#select-status").value;

    const rows = await window.aivicApi.list(4);
    if (rows) {
      allLogs = rows;
      let filtered = rows.filter(r => {
        let match = true;

        if (dateStart && r.検出日時) {
          const detectionDate = new Date(r.検出日時).toISOString().split('T')[0];
          if (detectionDate < dateStart) match = false;
        }

        if (dateEnd && r.検出日時) {
          const detectionDate = new Date(r.検出日時).toISOString().split('T')[0];
          if (detectionDate > dateEnd) match = false;
        }

        if (anomalyType && r.異常値種別 !== anomalyType) match = false;
        if (workerName && (!r.作業員名 || !r.作業員名.includes(workerName))) match = false;
        if (severity && r.重要度 !== severity) match = false;
        if (status && r.確認状況 !== status) match = false;

        return match;
      });

      renderRows(filtered);
    }
  });

  // 4. クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#input-date-start").value = "";
    container.querySelector("#input-date-end").value = "";
    container.querySelector("#select-anomaly-type").value = "";
    container.querySelector("#input-worker-name").value = "";
    container.querySelector("#select-severity").value = "";
    container.querySelector("#select-status").value = "";
    renderRows(allLogs);
  });

  // 5. 詳細表示・更新のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const logRow = e.target.closest(".log-row");

    if (detailBtn || (logRow && !e.target.closest("button"))) {
      const id = detailBtn ? detailBtn.dataset.id : logRow.dataset.id;
      const log = allLogs.find(l => l.id === id);

      if (log) {
        currentLogId = id;
        container.querySelector("#select-detail-status").value = log.確認状況 || "未確認";
        container.querySelector("#input-reviewer").value = log.確認者名 || "";
        container.querySelector("#textarea-memo").value = log.対応メモ || "";
        detailPanel.classList.remove("hidden");
      }
    }
  });

  // 詳細パネルの操作
  container.querySelector("#btn-update-status").addEventListener("click", async () => {
    if (!currentLogId) return;

    const status = container.querySelector("#select-detail-status").value;
    const memo = container.querySelector("#textarea-memo").value;

    const updated = await window.aivicApi.update(4, currentLogId, {
      確認状況: status,
      対応メモ: memo,
      確認者ID: "current-user-id", // 実際の実装では現在のユーザーIDを使用
      確認者名: "管理者", // 実際の実装では現在のユーザー名を使用
      確認日時: new Date().toISOString()
    });

    if (updated) {
      const rows = await window.aivicApi.list(4);
      if (rows) {
        allLogs = rows;
        renderRows(rows);
      }
      detailPanel.classList.add("hidden");
    }
  });

  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    detailPanel.classList.add("hidden");
    currentLogId = null;
  });

  container.querySelector("#btn-view-record").addEventListener("click", () => {
    window.showScreen("scr-1778907145716"); // 作業履歴一覧画面
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(4);
    if (!rows) return;

    const headers = ["検出日時", "作業員名", "異常値種別", "検出項目", "検出値", "閾値", "重要度", "確認状況", "対応メモ"];
    const csvContent = [
      headers.join(","),
      ...rows.map(r => [
        r.検出日時 ? `"${new Date(r.検出日時).toLocaleString('ja-JP')}"` : "",
        r.作業員名 ? `"${r.作業員名}"` : "",
        r.異常値種別 ? `"${r.異常値種別}"` : "",
        r.検出項目 ? `"${r.検出項目}"` : "",
        r.検出値 ? `"${r.検出値}"` : "",
        r.閾値 ? `"${r.閾値}"` : "",
        r.重要度 ? `"${r.重要度}"` : "",
        r.確認状況 ? `"${r.確認状況}"` : "",
        r.対応メモ ? `"${r.対応メモ.replace(/"/g, '""')}"` : ""
      ].join(","))
    ].join("\n");

    const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `異常値検出ログ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  // 現在日時の更新
  function updateDateTime() {
    const now = new Date();
    const dateStr = now.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
    container.querySelector('#current-datetime').textContent = dateStr;
  }
  updateDateTime();
  setInterval(updateDateTime, 60000); // 1分ごとに更新

  // 作業項目マスタの読み込み（テーブルインデックス3）
  function loadWorkItems() {
    window.aivicApi.list(3).then(items => {
      if (!items) return;
      const select = container.querySelector('#select-work-item');
      select.innerHTML = '<option value="">作業項目を選択してください</option>';
      items.filter(item => item.有効フラグ).forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        option.dataset.name = item.作業項目名;
        option.dataset.category = item.カテゴリ || '';
        select.appendChild(option);
      });
    });
  }

  // 進行中・中断中作業の表示
  function renderActiveWorks(works) {
    const activeContainer = container.querySelector('#active-works');
    const pausedContainer = container.querySelector('#paused-works');

    const activeWorks = works.filter(w => w.進捗状況 === '作業中');
    const pausedWorks = works.filter(w => w.進捗状況 === '中断');

    // 進行中作業
    if (activeWorks.length === 0) {
      activeContainer.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); padding: 8px;">進行中の作業はありません</div>';
    } else {
      activeContainer.innerHTML = activeWorks.map(work => {
        const startTime = new Date(work.作業開始時刻);
        const elapsed = Math.floor((Date.now() - startTime.getTime()) / 60000);
        return `
          <div style="background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; padding: 8px; margin-bottom: 8px;">
            <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 4px;">${work.作業種別}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">${work.作業場所}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 6px;">経過時間: ${elapsed}分</div>
            <div style="display: flex; gap: 4px;">
              <button class="action-btn secondary pause-btn" data-id="${work.作業記録ID}" style="padding: 4px 8px; font-size: 11px;">中断</button>
              <button class="action-btn secondary end-btn" data-id="${work.作業記録ID}" style="padding: 4px 8px; font-size: 11px;">終了</button>
            </div>
          </div>
        `;
      }).join('');
    }

    // 中断中作業
    if (pausedWorks.length === 0) {
      pausedContainer.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); padding: 8px;">中断中の作業はありません</div>';
    } else {
      pausedContainer.innerHTML = pausedWorks.map(work => {
        return `
          <div style="background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; padding: 8px; margin-bottom: 8px;">
            <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 4px;">${work.作業種別}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">${work.作業場所}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 6px;">中断中</div>
            <button class="action-btn resume-btn" data-id="${work.作業記録ID}" style="background: var(--primary); color: #fff; padding: 4px 8px; font-size: 11px;">再開</button>
          </div>
        `;
      }).join('');
    }
  }

  // 作業記録の読み込み
  function loadWorkRecords() {
    window.aivicApi.list(1).then(works => {
      if (works) {
        // 現在のユーザーの未完了作業のみ表示
        const userWorks = works.filter(w => 
          w.作業員ID === 'current-user-id' && 
          (w.進捗状況 === '作業中' || w.進捗状況 === '中断')
        );
        renderActiveWorks(userWorks);
      }
    });
  }

  // 初期データ読み込み
  loadWorkItems();
  loadWorkRecords();

  // 作業開始ボタン
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const location = container.querySelector('#input-location').value.trim();
    const workItemSelect = container.querySelector('#select-work-item');
    const workItemId = workItemSelect.value;
    const workItemName = workItemSelect.selectedOptions[0]?.dataset.name || '';
    const notes = container.querySelector('#input-notes').value.trim();

    if (!location) {
      alert('作業場所を入力してください');
      return;
    }
    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }

    const workRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証情報から取得
      作業日: new Date().toISOString().split('T')[0],
      作業開始時刻: new Date().toISOString(),
      作業終了時刻: null,
      作業時間: null,
      プロジェクト名: 'デフォルトプロジェクト',
      作業場所: location,
      作業種別: workItemName,
      作業内容: notes || workItemName,
      進捗状況: '作業中',
      備考: notes,
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      // フォームクリア
      container.querySelector('#input-location').value = '';
      container.querySelector('#select-work-item').value = '';
      container.querySelector('#input-notes').value = '';

      // 作業一覧を更新
      loadWorkRecords();

      alert('作業を開始しました');
    }
  });

  // 工数入力画面への遷移
  container.querySelector('#btn-work-input').addEventListener('click', () => {
    window.showScreen("scr-1778907296658");
  });

  // 設定ボタン
  container.querySelector('#btn-settings').addEventListener('click', () => {
    alert('設定機能は未実装です');
  });

  // ログアウトボタン
  container.querySelector('#btn-logout').addEventListener('click', () => {
    if (confirm('ログアウトしますか？')) {
      window.location.href = './login.html';
    }
  });

  // 作業操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 中断ボタン
    const pauseBtn = e.target.closest('.pause-btn');
    if (pauseBtn) {
      const workId = pauseBtn.dataset.id;
      const updated = await window.aivicApi.update(1, workId, {
        進捗状況: '中断'
      });
      if (updated) {
        // 中断記録も作成
        await window.aivicApi.save(2, {
          作業記録ID: workId,
          中断開始日時: new Date().toISOString(),
          中断終了日時: null,
          中断理由区分: '一時中断',
          中断理由詳細: '作業員による一時中断',
          中断時間: null,
          影響度: '軽微',
          対応状況: '対応中',
          記録者ID: 'current-user-id'
        });
        loadWorkRecords();
      }
      return;
    }

    // 終了ボタン
    const endBtn = e.target.closest('.end-btn');
    if (endBtn) {
      const workId = endBtn.dataset.id;
      const now = new Date().toISOString();
      const updated = await window.aivicApi.update(1, workId, {
        作業終了時刻: now,
        進捗状況: '完了'
      });
      if (updated) {
        loadWorkRecords();
        alert('作業を終了しました');
      }
      return;
    }

    // 再開ボタン
    const resumeBtn = e.target.closest('.resume-btn');
    if (resumeBtn) {
      const workId = resumeBtn.dataset.id;
      const updated = await window.aivicApi.update(1, workId, {
        進捗状況: '作業中'
      });
      if (updated) {
        // 中断記録の終了時刻を更新
        const interruptions = await window.aivicApi.list(2);
        if (interruptions) {
          const activeInterruption = interruptions.find(i => 
            i.作業記録ID === workId && !i.中断終了日時
          );
          if (activeInterruption) {
            await window.aivicApi.update(2, activeInterruption.中断記録ID, {
              中断終了日時: new Date().toISOString(),
              対応状況: '解決済み'
            });
          }
        }
        loadWorkRecords();
      }
      return;
    }
  });

  // フォーカス時のスタイル適用
  const inputs = container.querySelectorAll('input, select, textarea');
  inputs.forEach(input => {
    input.addEventListener('focus', () => {
      input.style.outline = 'none';
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });
    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });
  });
}

function(container, apiUrl, tables) {
  // 現在進行中の作業記録を取得して表示
  async function loadCurrentWorkRecord() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      const currentRecord = workRecords.find(r => r.進捗状況 === '作業中' && !r.作業終了時刻);

      if (currentRecord) {
        // 作業情報を表示
        container.querySelector('#work-item-name').textContent = currentRecord.作業内容 || '';
        container.querySelector('#work-location').textContent = currentRecord.作業場所 || '';

        const startTime = new Date(currentRecord.作業開始時刻);
        const endTime = new Date();

        container.querySelector('#start-time').textContent = startTime.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
        container.querySelector('#end-time').textContent = endTime.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});

        // 中断時間を計算
        const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
        const workBreaks = breakRecords.filter(b => b.作業記録ID === currentRecord.作業記録ID);
        let totalBreakMinutes = 0;

        workBreaks.forEach(breakRecord => {
          if (breakRecord.中断時間) {
            totalBreakMinutes += breakRecord.中断時間;
          }
        });

        const totalMinutes = Math.floor((endTime - startTime) / (1000 * 60));
        const actualWorkMinutes = totalMinutes - totalBreakMinutes;

        container.querySelector('#total-time').textContent = formatMinutes(totalMinutes);
        container.querySelector('#break-time').textContent = formatMinutes(totalBreakMinutes);
        container.querySelector('#actual-work-time').textContent = formatMinutes(actualWorkMinutes);

        // 現在の記録IDを保存
        container.currentRecordId = currentRecord.作業記録ID;
      }
    } catch (error) {
      console.error('作業記録の読み込みに失敗しました:', error);
    }
  }

  function formatMinutes(minutes) {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins.toString().padStart(2, '0')}分`;
  }

  // 異常報告チェックボックスの表示制御
  container.querySelector('#has-issue').addEventListener('change', function() {
    const issueSection = container.querySelector('#issue-section');
    if (this.checked) {
      issueSection.classList.remove('hidden');
    } else {
      issueSection.classList.add('hidden');
      container.querySelector('#issue-detail').value = '';
    }
  });

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async function() {
    if (!container.currentRecordId) {
      alert('記録対象の作業が見つかりません');
      return;
    }

    const completionStatus = container.querySelector('#completion-status').value;
    const workMemo = container.querySelector('#work-memo').value.trim();
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueDetail = container.querySelector('#issue-detail').value.trim();

    if (hasIssue && !issueDetail) {
      alert('異常・問題の詳細を入力してください');
      return;
    }

    try {
      // 作業記録を更新
      const endTime = new Date();
      const startTimeText = container.querySelector('#start-time').textContent;
      const actualWorkTimeText = container.querySelector('#actual-work-time').textContent;
      const actualMinutes = parseTimeToMinutes(actualWorkTimeText);

      const updateData = {
        作業終了時刻: endTime.toISOString(),
        作業時間: actualMinutes,
        進捗状況: completionStatus,
        備考: workMemo,
        承認状態: hasIssue ? '要確認' : '未承認'
      };

      const updated = await window.aivicApi.update(1, container.currentRecordId, updateData);

      if (updated) {
        // 異常報告がある場合は異常値検出ログに記録
        if (hasIssue) {
          const logData = {
            検出対象テーブル: '作業記録',
            検出対象レコードID: container.currentRecordId,
            ユーザーID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
            異常値種別: '作業員報告',
            検出項目: '異常・問題報告',
            検出値: issueDetail,
            閾値: 'なし',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: true,
            検出日時: new Date().toISOString()
          };

          await window.aivicApi.save(4, logData);
        }

        alert('作業記録を確定しました');
        window.showScreen("scr-1778907226171"); // 記録確認画面へ遷移
      }
    } catch (error) {
      console.error('記録の確定に失敗しました:', error);
      alert('記録の確定に失敗しました');
    }
  });

  function parseTimeToMinutes(timeText) {
    const match = timeText.match(/(\d+)時間(\d+)分/);
    if (match) {
      return parseInt(match[1]) * 60 + parseInt(match[2]);
    }
    return 0;
  }

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    if (confirm('作業記録の確定をキャンセルしますか？\n入力した内容は保存されません。')) {
      // 前の画面に戻る（工数記録画面など）
      history.back();
    }
  });

  // 記録確認ボタン
  container.querySelector('#btn-view-record').addEventListener('click', function() {
    window.showScreen("scr-1778907226171");
  });

  // ボタンホバー効果
  container.querySelector('#btn-confirm').addEventListener('mouseenter', function() {
    this.style.background = 'var(--primary-hover)';
  });

  container.querySelector('#btn-confirm').addEventListener('mouseleave', function() {
    this.style.background = 'var(--primary)';
  });

  container.querySelector('#btn-cancel').addEventListener('mouseenter', function() {
    this.style.background = 'rgba(255,255,255,0.05)';
  });

  container.querySelector('#btn-cancel').addEventListener('mouseleave', function() {
    this.style.background = 'transparent';
  });

  container.querySelector('#btn-view-record').addEventListener('mouseenter', function() {
    this.style.background = 'rgba(255,255,255,0.05)';
  });

  container.querySelector('#btn-view-record').addEventListener('mouseleave', function() {
    this.style.background = 'transparent';
  });

  // 初期データ読み込み
  loadCurrentWorkRecord();
}

function(container, apiUrl, tables) {
  // ローカルストレージキー
  const LOCAL_STORAGE_KEY = 'work_records_local';
  const SETTINGS_KEY = 'auto_save_settings';

  // 設定のデフォルト値
  let settings = {
    saveInterval: 30,
    maxLocalRecords: 100,
    autoSaveEnabled: true
  };

  // 設定を読み込み
  function loadSettings() {
    const saved = localStorage.getItem(SETTINGS_KEY);
    if (saved) {
      settings = { ...settings, ...JSON.parse(saved) };
    }
    container.querySelector('#save-interval').value = settings.saveInterval;
    container.querySelector('#max-local-records').value = settings.maxLocalRecords;
  }

  // 設定を保存
  function saveSettings() {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }

  // ローカルデータを取得
  function getLocalData() {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  // ローカルデータを保存
  function saveLocalData(data) {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
  }

  // ローカルデータテーブルを再描画
  function renderLocalData() {
    const localData = getLocalData();
    const tbody = container.querySelector('#local-data-tbody');

    tbody.innerHTML = localData.map(record => `
      <tr data-id="${record.id}" style="border-bottom: 1px solid var(--border);">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.id.substring(0, 8)}...</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.workerName || '未設定'}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.workDate || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.projectName || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; 
                       background: ${record.synced ? '#22c55e' : '#f59e0b'}; color: #fff;">
            ${record.synced ? '同期済み' : '同期待ち'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.savedAt || ''}</td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary retry-sync-btn" data-id="${record.id}" 
                  style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); 
                         padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">
            再同期
          </button>
          <button class="action-btn secondary delete-local-btn" data-id="${record.id}"
                  style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); 
                         padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">
            削除
          </button>
        </td>
      </tr>
    `).join('');

    // 同期待ちデータ件数を更新
    const pendingCount = localData.filter(r => !r.synced).length;
    container.querySelector('#pending-sync-count').textContent = `${pendingCount}件`;
  }

  // ネットワーク状態を更新
  function updateNetworkStatus() {
    const statusEl = container.querySelector('#network-status');
    if (navigator.onLine) {
      statusEl.textContent = 'オンライン';
      statusEl.style.color = '#22c55e';
    } else {
      statusEl.textContent = 'オフライン';
      statusEl.style.color = '#ef4444';
    }
  }

  // エラー通知を表示
  function showError(message) {
    const errorEl = container.querySelector('#error-notification');
    const messageEl = container.querySelector('#error-message');
    messageEl.textContent = message;
    errorEl.style.display = 'block';
  }

  // エラー通知を非表示
  function hideError() {
    container.querySelector('#error-notification').style.display = 'none';
  }

  // 最終保存時刻を更新
  function updateLastSaveTime() {
    const now = new Date();
    const timeStr = now.toLocaleTimeString('ja-JP', { hour12: false });
    container.querySelector('#last-save-time').textContent = timeStr;
  }

  // CSVエクスポート
  function exportToCSV() {
    const localData = getLocalData();
    if (localData.length === 0) {
      alert('エクスポートするデータがありません。');
      return;
    }

    const headers = ['作業記録ID', '作業員名', '作業日', 'プロジェクト名', '同期状態', '保存時刻'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...localData.map(record => [
        record.id,
        record.workerName || '',
        record.workDate || '',
        record.projectName || '',
        record.synced ? '同期済み' : '同期待ち',
        record.savedAt || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `local_data_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 手動同期実行
  async function performManualSync() {
    const localData = getLocalData();
    const pendingData = localData.filter(r => !r.synced);

    if (pendingData.length === 0) {
      alert('同期待ちのデータはありません。');
      return;
    }

    let syncedCount = 0;
    for (const record of pendingData) {
      try {
        const saved = await window.aivicApi.save(1, {
          作業員ID: record.workerId,
          作業日: record.workDate,
          作業開始時刻: record.startTime,
          作業終了時刻: record.endTime,
          プロジェクト名: record.projectName,
          作業場所: record.workLocation,
          作業種別: record.workType,
          作業内容: record.workContent,
          進捗状況: record.progress,
          承認状態: '未承認',
          作成者ID: record.workerId
        });

        if (saved) {
          record.synced = true;
          syncedCount++;
        }
      } catch (error) {
        console.error('同期エラー:', error);
      }
    }

    saveLocalData(localData);
    renderLocalData();

    if (syncedCount > 0) {
      alert(`${syncedCount}件のデータを同期しました。`);
      hideError();
    } else {
      showError('同期に失敗しました。ネットワーク接続を確認してください。');
    }
  }

  // データ復旧開始
  async function startDataRecovery() {
    const date = container.querySelector('#recovery-date').value;
    const method = container.querySelector('#recovery-method').value;

    if (!date) {
      alert('復旧対象日付を選択してください。');
      return;
    }

    try {
      // 指定日のデータを取得
      const allRecords = await window.aivicApi.list(1);
      if (!allRecords) {
        showError('データの取得に失敗しました。');
        return;
      }

      const targetRecords = allRecords.filter(r => 
        r.作業日 && r.作業日.startsWith(date)
      );

      if (targetRecords.length === 0) {
        alert('指定日のデータが見つかりませんでした。');
        return;
      }

      // ローカルストレージに復旧データを保存
      const recoveryData = targetRecords.map(record => ({
        id: record.作業記録ID,
        workerId: record.作業員ID,
        workerName: record.作業員名 || '不明',
        workDate: record.作業日,
        startTime: record.作業開始時刻,
        endTime: record.作業終了時刻,
        projectName: record.プロジェクト名,
        workLocation: record.作業場所,
        workType: record.作業種別,
        workContent: record.作業内容,
        progress: record.進捗状況,
        synced: true,
        savedAt: new Date().toLocaleString('ja-JP')
      }));

      const existingData = getLocalData();
      const mergedData = [...existingData, ...recoveryData];
      saveLocalData(mergedData);
      renderLocalData();

      alert(`${recoveryData.length}件のデータを復旧しました。`);
    } catch (error) {
      console.error('復旧エラー:', error);
      showError('データ復旧に失敗しました。');
    }
  }

  // バックアップ作成
  function createBackup() {
    const localData = getLocalData();
    const backupData = {
      timestamp: new Date().toISOString(),
      records: localData,
      settings: settings
    };

    const backupContent = JSON.stringify(backupData, null, 2);
    const blob = new Blob([backupContent], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `work_records_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
  }

  // 初期化
  loadSettings();
  renderLocalData();
  updateNetworkStatus();
  updateLastSaveTime();

  // サンプルローカルデータを作成（初回のみ）
  if (getLocalData().length === 0) {
    const sampleData = [
      {
        id: 'local-001',
        workerId: 'user-001',
        workerName: '田中太郎',
        workDate: '2024-01-15',
        startTime: '09:00',
        endTime: '12:00',
        projectName: 'A棟設備点検',
        workLocation: 'A棟3階',
        workType: '点検',
        workContent: '空調設備の定期点検',
        progress: '完了',
        synced: false,
        savedAt: '2024-01-15 12:05:30'
      },
      {
        id: 'local-002',
        workerId: 'user-002',
        workerName: '佐藤花子',
        workDate: '2024-01-15',
        startTime: '13:00',
        endTime: '17:00',
        projectName: 'B棟配線工事',
        workLocation: 'B棟2階',
        workType: '設置',
        workContent: 'LAN配線の新設工事',
        progress: '作業中',
        synced: false,
        savedAt: '2024-01-15 14:30:15'
      },
      {
        id: 'local-003',
        workerId: 'user-003',
        workerName: '鈴木次郎',
        workDate: '2024-01-14',
        startTime: '10:00',
        endTime: '15:00',
        projectName: 'C棟修理作業',
        workLocation: 'C棟1階',
        workType: '修理',
        workContent: '照明器具の交換作業',
        progress: '完了',
        synced: true,
        savedAt: '2024-01-14 15:10:45'
      }
    ];
    saveLocalData(sampleData);
    renderLocalData();
  }

  // イベントリスナー設定
  container.querySelector('#btn-manual-sync').addEventListener('click', performManualSync);

  container.querySelector('#btn-settings').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面
  });

  container.querySelector('#btn-update-settings').addEventListener('click', () => {
    settings.saveInterval = parseInt(container.querySelector('#save-interval').value);
    settings.maxLocalRecords = parseInt(container.querySelector('#max-local-records').value);
    saveSettings();
    alert('設定を更新しました。');
  });

  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (confirm('ローカルデータをすべて削除しますか？この操作は取り消せません。')) {
      localStorage.removeItem(LOCAL_STORAGE_KEY);
      renderLocalData();
      alert('ローカルデータを削除しました。');
    }
  });

  container.querySelector('#btn-export-local').addEventListener('click', exportToCSV);

  container.querySelector('#btn-dismiss-error').addEventListener('click', hideError);

  container.querySelector('#btn-start-recovery').addEventListener('click', startDataRecovery);

  container.querySelector('#btn-backup-create').addEventListener('click', createBackup);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const retrySyncBtn = e.target.closest('.retry-sync-btn');
    const deleteLocalBtn = e.target.closest('.delete-local-btn');

    if (retrySyncBtn) {
      const recordId = retrySyncBtn.dataset.id;
      const localData = getLocalData();
      const record = localData.find(r => r.id === recordId);

      if (record && !record.synced) {
        try {
          const saved = await window.aivicApi.save(1, {
            作業員ID: record.workerId,
            作業日: record.workDate,
            作業開始時刻: record.startTime,
            作業終了時刻: record.endTime,
            プロジェクト名: record.projectName,
            作業場所: record.workLocation,
            作業種別: record.workType,
            作業内容: record.workContent,
            進捗状況: record.progress,
            承認状態: '未承認',
            作成者ID: record.workerId
          });

          if (saved) {
            record.synced = true;
            saveLocalData(localData);
            renderLocalData();
            alert('データを同期しました。');
            hideError();
          }
        } catch (error) {
          showError('同期に失敗しました。ネットワーク接続を確認してください。');
        }
      }
    }

    if (deleteLocalBtn) {
      if (confirm('このローカルデータを削除しますか？')) {
        const recordId = deleteLocalBtn.dataset.id;
        const localData = getLocalData();
        const filteredData = localData.filter(r => r.id !== recordId);
        saveLocalData(filteredData);
        renderLocalData();
      }
    }
  });

  // ネットワーク状態の監視
  window.addEventListener('online', updateNetworkStatus);
  window.addEventListener('offline', updateNetworkStatus);

  // 定期的な最終保存時刻更新（自動保存のシミュレーション）
  setInterval(() => {
    if (settings.autoSaveEnabled && navigator.onLine) {
      updateLastSaveTime();
    }
  }, settings.saveInterval * 1000);
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#records-tbody");
  const modal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");

  // 中断時間を計算する関数
  function calculateBreakTime(recordId, breakRecords) {
    const breaks = breakRecords.filter(b => b.作業記録ID === recordId);
    return breaks.reduce((total, b) => total + (b.中断時間 || 0), 0);
  }

  // 異常値チェック関数
  function hasAnomalies(record, anomalyLogs) {
    return anomalyLogs.some(log => 
      log.検出対象レコードID === record.作業記録ID && 
      log.確認状況 === '未確認'
    );
  }

  // 時間フォーマット関数
  function formatMinutes(minutes) {
    if (!minutes) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // 再描画関数
  function renderRows(records) {
    const breakRecords = tables[2]?.records || [];
    const anomalyLogs = tables[4]?.records || [];

    tbody.innerHTML = records.map(record => {
      const breakTime = calculateBreakTime(record.作業記録ID, breakRecords);
      const hasAnomaly = hasAnomalies(record, anomalyLogs);
      const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '-';
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '作業中';

      return `
        <tr data-id="${record.作業記録ID}" style="height: 36px;">
          <td style="padding: 6px 10px; font-size: 13px;">${workDate}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${record.作業種別 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${endTime}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            ${formatMinutes(record.作業時間)}
            ${hasAnomaly ? '<span style="color: #ff6a00; margin-left: 4px;">⚠</span>' : ''}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatMinutes(breakTime)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; 
              ${record.承認状態 === '承認済み' ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 
                record.承認状態 === '差し戻し' ? 'background: rgba(239, 68, 68, 0.2); color: #ef4444;' : 
                'background: rgba(251, 191, 36, 0.2); color: #fbbf24;'}">
              ${record.承認状態 || '未承認'}
            </span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 11px; margin-right: 4px;">詳細</button>
            <button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 11px; margin-right: 4px;">修正</button>
            <button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 11px;">削除</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ表示
  renderRows(tables[1]?.records || []);

  // フィルター機能
  container.querySelector("#btn-filter").addEventListener("click", async () => {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const approval = container.querySelector("#filter-approval").value;

    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    const filtered = allRecords.filter(record => {
      const recordDate = record.作業日 ? new Date(record.作業日).toISOString().split('T')[0] : '';

      if (startDate && recordDate < startDate) return false;
      if (endDate && recordDate > endDate) return false;
      if (approval && record.承認状態 !== approval) return false;

      return true;
    });

    renderRows(filtered);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const records = await window.aivicApi.list(1);
    if (!records) return;

    const headers = ['作業日', '作業種別', '作業場所', '開始時刻', '終了時刻', '作業時間', '作業内容', '承認状態'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...records.map(record => [
        record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '',
        record.作業種別 || '',
        record.作業場所 || '',
        record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP') : '',
        record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP') : '',
        formatMinutes(record.作業時間),
        `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
        record.承認状態 || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // メニューに戻る
  container.querySelector("#btn-menu").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 詳細表示
  function showDetail(recordId) {
    const record = tables[1]?.records?.find(r => r.作業記録ID === recordId);
    if (!record) return;

    const breakRecords = tables[2]?.records?.filter(b => b.作業記録ID === recordId) || [];

    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 120px 1fr; gap: 8px; margin-bottom: 16px;">
        <div style="font-weight: 600;">作業日:</div>
        <div>${record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '-'}</div>
        <div style="font-weight: 600;">プロジェクト:</div>
        <div>${record.プロジェクト名 || '-'}</div>
        <div style="font-weight: 600;">作業場所:</div>
        <div>${record.作業場所 || '-'}</div>
        <div style="font-weight: 600;">作業種別:</div>
        <div>${record.作業種別 || '-'}</div>
        <div style="font-weight: 600;">開始時刻:</div>
        <div>${record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleString('ja-JP') : '-'}</div>
        <div style="font-weight: 600;">終了時刻:</div>
        <div>${record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleString('ja-JP') : '作業中'}</div>
        <div style="font-weight: 600;">作業時間:</div>
        <div>${formatMinutes(record.作業時間)}</div>
        <div style="font-weight: 600;">進捗状況:</div>
        <div>${record.進捗状況 || '-'}</div>
        <div style="font-weight: 600;">承認状態:</div>
        <div>${record.承認状態 || '未承認'}</div>
      </div>
      <div style="margin-bottom: 16px;">
        <div style="font-weight: 600; margin-bottom: 8px;">作業内容:</div>
        <div style="background: rgba(0,0,0,0.1); padding: 8px; border-radius: 4px; white-space: pre-wrap;">${record.作業内容 || '-'}</div>
      </div>
      ${record.備考 ? `
      <div style="margin-bottom: 16px;">
        <div style="font-weight: 600; margin-bottom: 8px;">備考:</div>
        <div style="background: rgba(0,0,0,0.1); padding: 8px; border-radius: 4px; white-space: pre-wrap;">${record.備考}</div>
      </div>
      ` : ''}
      ${breakRecords.length > 0 ? `
      <div>
        <div style="font-weight: 600; margin-bottom: 8px;">中断記録:</div>
        ${breakRecords.map(br => `
          <div style="background: rgba(0,0,0,0.1); padding: 8px; border-radius: 4px; margin-bottom: 4px;">
            <div>理由: ${br.中断理由区分 || '-'}</div>
            <div>時間: ${formatMinutes(br.中断時間)}</div>
            ${br.中断理由詳細 ? `<div>詳細: ${br.中断理由詳細}</div>` : ''}
          </div>
        `).join('')}
      </div>
      ` : ''}
    `;

    modal.classList.remove('hidden');
  }

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    modal.classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const editBtn = e.target.closest(".edit-btn");
    const deleteBtn = e.target.closest(".delete-btn");

    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }

    if (editBtn) {
      window.showScreen("scr-1778907343735");
    }

    if (deleteBtn) {
      if (!confirm("この作業記録を削除しますか？")) return;

      const success = await window.aivicApi.delete(1, deleteBtn.dataset.id);
      if (success) {
        const records = await window.aivicApi.list(1);
        if (records) renderRows(records);
      }
    }
  });

  // モーダル背景クリックで閉じる
  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      modal.classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  // 現在時刻を中断開始時刻にセット
  const now = new Date();
  const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
  container.querySelector('#interruption-start-time').value = localDateTime;

  // 中断時間の自動計算
  let startTime = now;
  function updateDuration() {
    const currentTime = new Date();
    const diffMs = currentTime - startTime;
    const minutes = Math.floor(diffMs / 60000);
    const seconds = Math.floor((diffMs % 60000) / 1000);
    container.querySelector('#interruption-duration').textContent = 
      `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}`;
  }

  // 1秒ごとに時間更新
  const durationInterval = setInterval(updateDuration, 1000);
  updateDuration();

  // 中断開始時刻変更時の処理
  container.querySelector('#interruption-start-time').addEventListener('change', function() {
    const newStartTime = new Date(this.value);
    if (!isNaN(newStartTime.getTime())) {
      startTime = newStartTime;
      updateDuration();
    }
  });

  // 写真添付ボタン
  container.querySelector('#btn-photo').addEventListener('click', function() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.addEventListener('change', function() {
      if (this.files.length > 0) {
        container.querySelector('#attachment-status').textContent = `写真: ${this.files[0].name}`;
      }
    });
    input.click();
  });

  // 音声メモボタン
  let isRecording = false;
  container.querySelector('#btn-voice').addEventListener('click', function() {
    if (!isRecording) {
      isRecording = true;
      this.textContent = '🔴 録音停止';
      this.style.background = 'var(--primary)';
      this.style.color = '#fff';
      container.querySelector('#attachment-status').textContent = '録音中...';
    } else {
      isRecording = false;
      this.textContent = '🎤 音声メモ';
      this.style.background = 'transparent';
      this.style.color = 'var(--text)';
      container.querySelector('#attachment-status').textContent = '音声メモ: 録音完了';
    }
  });

  // 一時保存ボタン
  container.querySelector('#btn-temp-save').addEventListener('click', async function() {
    const formData = collectFormData();
    formData.対応状況 = '対応中';

    const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル
    if (saved) {
      alert('一時保存しました');
    }
  });

  // フォームデータ収集関数
  function collectFormData() {
    const urgencyRadio = container.querySelector('input[name="urgency"]:checked');
    const impactCheckboxes = container.querySelectorAll('input[type="checkbox"]:checked');
    const impactValues = Array.from(impactCheckboxes).map(cb => cb.value);

    const currentTime = new Date();
    const diffMs = currentTime - startTime;
    const interruptionMinutes = Math.floor(diffMs / 60000);

    return {
      作業記録ID: 'current-work-id', // 実際の実装では現在の作業記録IDを取得
      中断開始日時: container.querySelector('#interruption-start-time').value,
      中断理由区分: container.querySelector('#interruption-reason').value,
      中断理由詳細: container.querySelector('#interruption-details').value,
      中断時間: interruptionMinutes,
      影響度: urgencyRadio ? urgencyRadio.value : '中',
      対応状況: '解決済み',
      記録者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを取得
    };
  }

  // フォーム送信処理
  container.querySelector('#interruption-form').addEventListener('submit', async function(e) {
    e.preventDefault();

    const formData = collectFormData();
    formData.中断終了日時 = new Date().toISOString();
    formData.対応状況 = '解決済み';

    const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル
    if (saved) {
      alert('中断記録を完了しました');
      window.showScreen("scr-1778907251446"); // 作業再開記録画面
    }
  });

  // クリーンアップ関数を返す（画面切り替え時にインターバルをクリア）
  return function cleanup() {
    if (durationInterval) {
      clearInterval(durationInterval);
    }
  };
}

function(container, apiUrl, tables) {
  let selectedSuspendRecord = null;
  let currentWorkRecord = null;

  // 中断記録一覧の再描画
  function renderSuspendedWork(suspendRecords) {
    const tbody = container.querySelector("#suspended-work-list");
    if (!suspendRecords || suspendRecords.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; color: var(--text-muted); padding: 20px;">中断中の作業はありません</td></tr>';
      return;
    }

    tbody.innerHTML = suspendRecords.map(record => {
      const suspendTime = record.中断時間 ? `${record.中断時間}分` : '-';
      const startTime = record.中断開始日時 ? new Date(record.中断開始日時).toLocaleString('ja-JP', {
        month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit'
      }) : '-';

      return `
        <tr data-id="${record.中断記録ID}" style="cursor: pointer;">
          <td style="font-weight: 500;">${record.作業項目名 || '-'}</td>
          <td>${startTime}</td>
          <td>${record.中断理由区分 || '-'}</td>
          <td>${suspendTime}</td>
          <td>
            <button class="action-btn resume-btn" data-id="${record.中断記録ID}" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">選択</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 現在時刻を更新
  function updateCurrentTime() {
    const now = new Date();
    const timeStr = now.toLocaleString('ja-JP', {
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
    const resumeTimeEl = container.querySelector("#resume-time");
    if (resumeTimeEl) {
      resumeTimeEl.textContent = timeStr;
    }
  }

  // 作業再開フォームを表示
  function showResumeForm(suspendRecord, workRecord) {
    selectedSuspendRecord = suspendRecord;
    currentWorkRecord = workRecord;

    const form = container.querySelector("#resume-form");
    form.style.display = "block";

    // フォーム項目を設定
    container.querySelector("#selected-work-name").textContent = workRecord?.作業内容 || '-';
    container.querySelector("#suspend-start-time").textContent = suspendRecord.中断開始日時 ? 
      new Date(suspendRecord.中断開始日時).toLocaleString('ja-JP') : '-';
    container.querySelector("#suspend-reason").textContent = suspendRecord.中断理由詳細 || suspendRecord.中断理由区分 || '-';

    updateCurrentTime();

    // 1秒ごとに時刻を更新
    const timeInterval = setInterval(updateCurrentTime, 1000);
    form.dataset.timeInterval = timeInterval;

    // フォームをリセット
    container.querySelector("#resume-reason-select").value = "";
    container.querySelector("#resume-reason-detail").value = "";
  }

  // 作業再開フォームを非表示
  function hideResumeForm() {
    const form = container.querySelector("#resume-form");
    form.style.display = "none";

    // 時刻更新を停止
    if (form.dataset.timeInterval) {
      clearInterval(parseInt(form.dataset.timeInterval));
      delete form.dataset.timeInterval;
    }

    selectedSuspendRecord = null;
    currentWorkRecord = null;
  }

  // 確認ダイアログを表示
  function showConfirmDialog() {
    const reasonSelect = container.querySelector("#resume-reason-select").value;
    const reasonDetail = container.querySelector("#resume-reason-detail").value;

    if (!reasonSelect) {
      alert("再開理由区分を選択してください");
      return;
    }

    const dialog = container.querySelector("#resume-confirm-dialog");
    const details = container.querySelector("#confirm-details");

    details.innerHTML = `
      <div>作業項目: ${currentWorkRecord?.作業内容 || '-'}</div>
      <div>再開理由: ${reasonSelect}</div>
      ${reasonDetail ? `<div>詳細: ${reasonDetail}</div>` : ''}
    `;

    dialog.style.display = "flex";
  }

  // 確認ダイアログを非表示
  function hideConfirmDialog() {
    const dialog = container.querySelector("#resume-confirm-dialog");
    dialog.style.display = "none";
  }

  // 作業を再開
  async function resumeWork() {
    const reasonSelect = container.querySelector("#resume-reason-select").value;
    const reasonDetail = container.querySelector("#resume-reason-detail").value;
    const resumeTime = new Date().toISOString();

    try {
      // 中断記録を更新（終了時刻を設定）
      const updatedSuspend = await window.aivicApi.update(2, selectedSuspendRecord.中断記録ID, {
        中断終了日時: resumeTime,
        中断時間: Math.floor((new Date(resumeTime) - new Date(selectedSuspendRecord.中断開始日時)) / 60000)
      });

      if (!updatedSuspend) {
        alert("中断記録の更新に失敗しました");
        return;
      }

      // 作業記録を更新（進捗状況を「作業中」に変更）
      const updatedWork = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, {
        進捗状況: "作業中",
        備考: `${currentWorkRecord.備考 || ''}\n[${new Date().toLocaleString('ja-JP')}] 作業再開: ${reasonSelect}${reasonDetail ? ` - ${reasonDetail}` : ''}`
      });

      if (!updatedWork) {
        alert("作業記録の更新に失敗しました");
        return;
      }

      hideConfirmDialog();
      hideResumeForm();

      // 工数入力画面に遷移
      window.showScreen("scr-1778907296658");

    } catch (error) {
      console.error("作業再開エラー:", error);
      alert("作業再開に失敗しました");
    }
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      // 中断記録を取得（中断終了日時がnullのもの）
      const suspendRecords = await window.aivicApi.list(2);
      const activeSuspends = suspendRecords ? suspendRecords.filter(r => !r.中断終了日時) : [];

      // 作業記録を取得
      const workRecords = await window.aivicApi.list(1);

      // 中断記録に作業項目名を追加
      const enrichedSuspends = activeSuspends.map(suspend => {
        const work = workRecords?.find(w => w.作業記録ID === suspend.作業記録ID);
        return {
          ...suspend,
          作業項目名: work?.作業内容 || '不明な作業'
        };
      });

      renderSuspendedWork(enrichedSuspends);

    } catch (error) {
      console.error("データ読み込みエラー:", error);
      renderSuspendedWork([]);
    }
  }

  // イベントリスナー設定
  container.addEventListener("click", async (e) => {
    // 作業選択ボタン
    const resumeBtn = e.target.closest(".resume-btn");
    if (resumeBtn) {
      const suspendId = resumeBtn.dataset.id;
      const suspendRecords = await window.aivicApi.list(2);
      const workRecords = await window.aivicApi.list(1);

      const suspendRecord = suspendRecords?.find(r => r.中断記録ID === suspendId);
      const workRecord = workRecords?.find(w => w.作業記録ID === suspendRecord?.作業記録ID);

      if (suspendRecord && workRecord) {
        showResumeForm(suspendRecord, workRecord);
      }
      return;
    }

    // 作業再開ボタン
    if (e.target.id === "btn-resume-work") {
      showConfirmDialog();
      return;
    }

    // キャンセルボタン
    if (e.target.id === "btn-cancel") {
      hideResumeForm();
      return;
    }

    // 確認ダイアログ - 再開ボタン
    if (e.target.id === "btn-confirm-resume") {
      await resumeWork();
      return;
    }

    // 確認ダイアログ - キャンセルボタン
    if (e.target.id === "btn-confirm-cancel") {
      hideConfirmDialog();
      return;
    }

    // 戻るボタン
    if (e.target.id === "btn-back") {
      window.history.back();
      return;
    }
  });

  // 初期データ読み込み
  loadData();
}

