      field: 'work_time'
    },
    {
      id: 'check-3',
      type: 'error', 
      category: '入力形式',
      message: 'プロジェクト名に使用できない文字が含まれています',
      targetValue: 'プロジェクト@#$',
      field: 'project_name'
    },
    {
      id: 'check-4',
      type: 'warning',
      category: '作業時間妥当性',
      message: '作業時間が12時間を超過しています',
      targetValue: '12:30',
      field: 'work_duration'
    },
    {
      id: 'check-5',
      type: 'warning',
      category: '重複データ',
      message: '同じ時間帯の作業記録が既に存在します',
      targetValue: '2024-01-15 09:00',
      field: 'work_start_time'
    },
    {
      id: 'check-6',
      type: 'info',
      category: '入力形式',
      message: '作業内容の文字数が推奨範囲を下回っています',
      targetValue: '点検作業',
      field: 'work_content'
    }
  ];

  let currentCheckResults = [...sampleCheckResults];

  // チェック結果テーブル再描画
  function renderCheckResults(results) {
    const tbody = container.querySelector('#check-results-tbody');
    tbody.innerHTML = results.map(result => {
      const typeIcon = result.type === 'error' ? '❌' : result.type === 'warning' ? '⚠️' : 'ℹ️';
      const typeColor = result.type === 'error' ? '#dc2626' : result.type === 'warning' ? '#ffa500' : '#3b82f6';

      return `
        <tr data-id="${result.id}">
          <td style="text-align: center;">
            <span style="color: ${typeColor};">${typeIcon}</span>
          </td>
          <td style="font-size: 12px; color: var(--text);">${result.category}</td>
          <td style="font-size: 12px; color: var(--text);">${result.message}</td>
          <td style="font-size: 12px; color: var(--text-muted);">${result.targetValue}</td>
          <td>
            <button class="action-btn secondary fix-btn" data-id="${result.id}" style="font-size: 11px; padding: 3px 6px;">
              修正
            </button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(results);
  }

  // サマリー更新
  function updateSummary(results) {
    const errorCount = results.filter(r => r.type === 'error').length;
    const warningCount = results.filter(r => r.type === 'warning').length;

    container.querySelector('#error-count').textContent = errorCount;
    container.querySelector('#warning-count').textContent = warningCount;

    const statusIcon = container.querySelector('#status-icon');
    const statusText = container.querySelector('#status-text');
    const saveStatus = container.querySelector('#save-status');

    if (errorCount > 0) {
      statusIcon.textContent = '❌';
      statusText.textContent = 'エラーあり';
      statusText.style.color = '#dc2626';
      saveStatus.textContent = '不可';
      saveStatus.style.color = '#dc2626';
    } else if (warningCount > 0) {
      statusIcon.textContent = '⚠️';
      statusText.textContent = '警告あり';
      statusText.style.color = '#ffa500';
      saveStatus.textContent = '可能';
      saveStatus.style.color = '#10b981';
    } else {
      statusIcon.textContent = '✅';
      statusText.textContent = 'OK';
      statusText.style.color = '#10b981';
      saveStatus.textContent = '可能';
      saveStatus.style.color = '#10b981';
    }
  }

  // フィルタリング
  function applyFilters() {
    const typeFilter = container.querySelector('#filter-type').value;
    const keyword = container.querySelector('#filter-keyword').value.toLowerCase();

    let filtered = currentCheckResults;

    if (typeFilter) {
      filtered = filtered.filter(r => r.type === typeFilter);
    }

    if (keyword) {
      filtered = filtered.filter(r => 
        r.message.toLowerCase().includes(keyword) ||
        r.category.toLowerCase().includes(keyword) ||
        r.targetValue.toLowerCase().includes(keyword)
      );
    }

    renderCheckResults(filtered);
  }

  // 修正提案適用
  window.applySuggestion = function(field, value) {
    alert(`${field} を ${value} に修正しました`);
    // 実際の修正処理をここに実装
    window.showScreen('scr-1778907319067'); // 修正入力画面へ
  };

  // 初期描画
  renderCheckResults(currentCheckResults);

  // イベントリスナー
  container.querySelector('#filter-type').addEventListener('change', applyFilters);
  container.querySelector('#filter-keyword').addEventListener('input', applyFilters);

  container.querySelector('#btn-refresh').addEventListener('click', async () => {
    // 最新のチェック結果を取得（実際はAPIから）
    renderCheckResults(currentCheckResults);
  });

  container.querySelector('#btn-clear-all').addEventListener('click', () => {
    if (confirm('全てのチェック結果をクリアしますか？')) {
      currentCheckResults = [];
      renderCheckResults(currentCheckResults);
    }
  });

  container.querySelector('#btn-export-log').addEventListener('click', () => {
    const csvContent = '\uFEFF' + [
      'チェック種別,項目,メッセージ,対象値',
      ...currentCheckResults.map(r => `${r.type},${r.category},"${r.message}",${r.targetValue}`)
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'check_results.csv';
    a.click();
    URL.revokeObjectURL(url);
  });

  container.querySelector('#btn-fix-errors').addEventListener('click', () => {
    window.showScreen('scr-1778907319067'); // 修正入力画面
  });

  container.querySelector('#btn-view-details').addEventListener('click', () => {
    window.showScreen('scr-1778907226171'); // 記録確認画面
  });

  container.querySelector('#btn-emergency-report').addEventListener('click', () => {
    window.showScreen('scr-1778907330826'); // 緊急報告画面
  });

  // 行レベル操作
  container.addEventListener('click', (e) => {
    const fixBtn = e.target.closest('.fix-btn');
    if (fixBtn) {
      const checkId = fixBtn.dataset.id;
      const checkResult = currentCheckResults.find(r => r.id === checkId);
      if (checkResult) {
        window.showScreen('scr-1778907319067'); // 修正入力画面
      }
    }
  });
}

function(container, apiUrl, tables) {
  // エラー情報の初期化（URLパラメータやlocalStorageから取得可能）
  const errorInfo = {
    title: "システムエラーが発生しました",
    message: "予期しないエラーが発生しました。しばらく時間をおいて再度お試しください。",
    code: "ERR_500_INTERNAL",
    timestamp: new Date().toLocaleString('ja-JP'),
    solution: "1. ページを再読み込みしてください\n2. 問題が続く場合は管理者にお問い合わせください\n3. 緊急の場合は直接お電話でご連絡ください"
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      Object.assign(errorInfo, errorData);
    } catch (e) {
      console.warn('エラー情報の解析に失敗しました:', e);
    }
  }

  // エラー情報を画面に反映
  container.querySelector('#error-title').textContent = errorInfo.title;
  container.querySelector('#error-message').textContent = errorInfo.message;
  container.querySelector('#error-code').textContent = errorInfo.code;
  container.querySelector('#error-timestamp').textContent = errorInfo.timestamp;
  container.querySelector('#error-solution').innerHTML = errorInfo.solution.replace(/\n/g, '<br>');

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', () => {
    // 前の画面に戻って再実行
    if (window.history.length > 1) {
      window.history.back();
      setTimeout(() => {
        window.location.reload();
      }, 100);
    } else {
      window.location.reload();
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面（ホーム画面として）
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact').addEventListener('click', () => {
    // 緊急報告画面に遷移してエラー情報を引き継ぐ
    const errorData = encodeURIComponent(JSON.stringify({
      type: 'system_error',
      title: errorInfo.title,
      message: errorInfo.message,
      code: errorInfo.code,
      timestamp: errorInfo.timestamp,
      url: window.location.href,
      userAgent: navigator.userAgent
    }));
    window.showScreen('scr-1778907330826', { error: errorData }); // 緊急報告画面
  });

  // エラー詳細表示切り替え
  container.querySelector('#btn-toggle-details').addEventListener('click', () => {
    const detailsDiv = container.querySelector('#error-details');
    const toggleBtn = container.querySelector('#btn-toggle-details');

    if (detailsDiv.classList.contains('hidden')) {
      detailsDiv.classList.remove('hidden');
      toggleBtn.textContent = 'エラー詳細を非表示';
    } else {
      detailsDiv.classList.add('hidden');
      toggleBtn.textContent = 'エラー詳細を表示';
    }
  });

  // キーボードショートカット
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      // ESCキーでホームに戻る
      window.showScreen('scr-1778907133295');
    } else if (e.key === 'F5' || (e.ctrlKey && e.key === 'r')) {
      // F5またはCtrl+Rで再試行
      e.preventDefault();
      container.querySelector('#btn-retry').click();
    }
  });

  // 自動リロード機能（30秒後）
  let autoReloadTimer = setTimeout(() => {
    if (confirm('30秒が経過しました。自動的に再試行しますか？')) {
      container.querySelector('#btn-retry').click();
    }
  }, 30000);

  // 画面を離れる時にタイマーをクリア
  const cleanup = () => {
    if (autoReloadTimer) {
      clearTimeout(autoReloadTimer);
      autoReloadTimer = null;
    }
  };

  // クリーンアップ関数を登録
  if (container.cleanup) {
    const originalCleanup = container.cleanup;
    container.cleanup = () => {
      cleanup();
      originalCleanup();
    };
  } else {
    container.cleanup = cleanup;
  }
}

function(container, apiUrl, tables) {
  let currentData = [];
  let filteredData = [];

  // 再描画関数
  function renderValidationResults(results) {
    const tbody = container.querySelector('#validation-results');
    const resultCount = container.querySelector('#result-count');

    resultCount.textContent = `${results.length}件`;

    tbody.innerHTML = results.map(r => {
      const severityColor = r.重要度 === '高' ? '#ff4444' : r.重要度 === '中' ? '#ff8800' : '#44aa44';
      const statusColor = r.確認状況 === '未確認' ? '#ff8800' : r.確認状況 === '確認済み' ? '#4488ff' : '#44aa44';

      return `
        <tr data-id="${r.id || r.異常値検出ログID}">
          <td><input type="checkbox" class="row-check" data-id="${r.id || r.異常値検出ログID}" style="accent-color: var(--primary);"></td>
          <td>${new Date(r.検出日時 || r.作成日時).toLocaleString()}</td>
          <td>${r.作業員名 || 'N/A'}</td>
          <td>${r.異常値種別 || ''}</td>
          <td>${r.検出項目 || ''}</td>
          <td style="font-weight: 500;">${r.検出値 || ''}</td>
          <td>${r.閾値 || ''}</td>
          <td><span style="color: ${severityColor}; font-weight: 500;">●</span> ${r.重要度 || ''}</td>
          <td><span style="color: ${statusColor}; font-weight: 500;">●</span> ${r.確認状況 || ''}</td>
          <td>
            <button class="action-btn secondary correct-btn" data-id="${r.id || r.異常値検出ログID}" style="font-size: 11px; padding: 4px 8px;">修正</button>
            <button class="action-btn secondary confirm-btn" data-id="${r.id || r.異常値検出ログID}" style="font-size: 11px; padding: 4px 8px;">確認</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 通知表示
  function showNotification(message, type = 'info') {
    const area = container.querySelector('#notification-area');
    const icon = container.querySelector('#notification-icon');
    const text = container.querySelector('#notification-text');

    const colors = {
      success: '#44aa44',
      error: '#ff4444',
      warning: '#ff8800',
      info: '#4488ff'
    };

    icon.style.background = colors[type] || colors.info;
    text.textContent = message;
    area.classList.remove('hidden');

    setTimeout(() => {
      area.classList.add('hidden');
    }, 3000);
  }

  // 検証実行
  async function executeValidation() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const target = container.querySelector('#select-target').value;

    if (!startDate || !endDate) {
      showNotification('検証期間を指定してください', 'warning');
      return;
    }

    const progressArea = container.querySelector('#progress-area');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressArea.classList.remove('hidden');

    // 進捗シミュレーション
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 20;
      if (progress > 100) progress = 100;

      progressBar.style.width = `${progress}%`;
      progressText.textContent = `${Math.floor(progress)}%`;

      if (progress >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          progressArea.classList.add('hidden');
          showNotification('検証が完了しました', 'success');
          loadValidationResults();
        }, 500);
      }
    }, 200);
  }

  // 検証結果読み込み
  async function loadValidationResults() {
    try {
      const results = await window.aivicApi.list(4); // 異常値検出ログテーブル
      if (results) {
        currentData = results;
        applyFilters();
      }
    } catch (error) {
      showNotification('データの読み込みに失敗しました', 'error');
    }
  }

  // フィルター適用
  function applyFilters() {
    const errorType = container.querySelector('#filter-error-type').value;
    const severity = container.querySelector('#filter-severity').value;
    const status = container.querySelector('#filter-status').value;

    filteredData = currentData.filter(item => {
      return (!errorType || item.異常値種別 === errorType) &&
             (!severity || item.重要度 === severity) &&
             (!status || item.確認状況 === status);
    });

    renderValidationResults(filteredData);
  }

  // データ修正モーダル表示
  function showCorrectionModal(recordId) {
    const modal = container.querySelector('#correction-modal');
    const form = container.querySelector('#correction-form');
    const record = currentData.find(r => (r.id || r.異常値検出ログID) === recordId);

    if (!record) return;

    form.innerHTML = `
      <div style="margin-bottom: 12px;">
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">検出項目</label>
        <input type="text" id="correct-item" value="${record.検出項目 || ''}" style="padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px; width: 100%;" readonly>
      </div>
      <div style="margin-bottom: 12px;">
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">現在の値</label>
        <input type="text" id="correct-current" value="${record.検出値 || ''}" style="padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px; width: 100%;">
      </div>
      <div style="margin-bottom: 12px;">
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">対応メモ</label>
        <textarea id="correct-memo" style="padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px; width: 100%; height: 60px; resize: vertical;">${record.対応メモ || ''}</textarea>
      </div>
    `;

    modal.classList.remove('hidden');
    modal.dataset.recordId = recordId;
  }

  // 一括承認
  async function bulkApprove() {
    const checkedBoxes = container.querySelectorAll('.row-check:checked');
    if (checkedBoxes.length === 0) {
      showNotification('承認する項目を選択してください', 'warning');
      return;
    }

    if (!confirm(`${checkedBoxes.length}件の項目を一括承認しますか？`)) return;

    try {
      for (const checkbox of checkedBoxes) {
        const id = checkbox.dataset.id;
        await window.aivicApi.update(4, id, {
          確認状況: '対応済み',
          確認日時: new Date().toISOString(),
          確認者ID: 'current-user-id'
        });
      }

      showNotification(`${checkedBoxes.length}件を承認しました`, 'success');
      loadValidationResults();
    } catch (error) {
      showNotification('一括承認に失敗しました', 'error');
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (filteredData.length === 0) {
      showNotification('エクスポートするデータがありません', 'warning');
      return;
    }

    const headers = ['検出日時', '作業員', 'エラー種別', '検出項目', '検出値', '閾値', '重要度', '確認状況', '対応メモ'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...filteredData.map(r => [
        `"${new Date(r.検出日時 || r.作成日時).toLocaleString()}"`,
        `"${r.作業員名 || 'N/A'}"`,
        `"${r.異常値種別 || ''}"`,
        `"${r.検出項目 || ''}"`,
        `"${r.検出値 || ''}"`,
        `"${r.閾値 || ''}"`,
        `"${r.重要度 || ''}"`,
        `"${r.確認状況 || ''}"`,
        `"${(r.対応メモ || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `validation_log_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();

    showNotification('検証ログをエクスポートしました', 'success');
  }

  // 初期データ表示
  renderValidationResults(tables[4]?.records || []);
  currentData = tables[4]?.records || [];
  filteredData = currentData;

  // 今日の日付を初期値に設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#input-start-date').value = today;
  container.querySelector('#input-end-date').value = today;

  // イベントリスナー
  container.querySelector('#btn-validate').addEventListener('click', executeValidation);
  container.querySelector('#btn-filter').addEventListener('click', applyFilters);
  container.querySelector('#btn-bulk-approve').addEventListener('click', bulkApprove);
  container.querySelector('#btn-export-log').addEventListener('click', exportCSV);
  container.querySelector('#btn-back').addEventListener('click', () => window.showScreen('scr-1778907145716'));

  // 全選択チェックボックス
  container.querySelector('#check-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-check');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 通知クローズ
  container.querySelector('#btn-close-notification').addEventListener('click', () => {
    container.querySelector('#notification-area').classList.add('hidden');
  });

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#correction-modal').classList.add('hidden');
  });

  container.querySelector('#btn-cancel-correction').addEventListener('click', () => {
    container.querySelector('#correction-modal').classList.add('hidden');
  });

  container.querySelector('#btn-save-correction').addEventListener('click', async () => {
    const modal = container.querySelector('#correction-modal');
    const recordId = modal.dataset.recordId;
    const memo = container.querySelector('#correct-memo').value;

    try {
      await window.aivicApi.update(4, recordId, {
        確認状況: '対応済み',
        対応メモ: memo,
        確認日時: new Date().toISOString(),
        確認者ID: 'current-user-id'
      });

      modal.classList.add('hidden');
      showNotification('修正を保存しました', 'success');
      loadValidationResults();
    } catch (error) {
      showNotification('修正の保存に失敗しました', 'error');
    }
  });

  // 行レベル操作
  container.addEventListener('click', async (e) => {
    const correctBtn = e.target.closest('.correct-btn');
    const confirmBtn = e.target.closest('.confirm-btn');

    if (correctBtn) {
      const id = correctBtn.dataset.id;
      showCorrectionModal(id);
    }

    if (confirmBtn) {
      const id = confirmBtn.dataset.id;
      if (confirm('この項目を確認済みにしますか？')) {
        try {
          await window.aivicApi.update(4, id, {
            確認状況: '確認済み',
            確認日時: new Date().toISOString(),
            確認者ID: 'current-user-id'
          });

          showNotification('確認済みに更新しました', 'success');
          loadValidationResults();
        } catch (error) {
          showNotification('更新に失敗しました', 'error');
        }
      }
    }
  });

  // 初期データ読み込み
  loadValidationResults();
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let savedInterruptions = [];
  let workStatus = 'not_started'; // not_started, in_progress, interrupted, completed

  // 現在のユーザー情報を設定（実際の実装では認証情報から取得）
  const currentUser = { id: 'user-001', name: '田中太郎' };
  container.querySelector('#worker-name').textContent = currentUser.name;

  // 作業項目マスタを読み込み
  function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    if (workItemsTable && workItemsTable.records) {
      workItemsTable.records
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        });
    }
  }

  // 実働時間を計算・表示
  function updateActualWorkTime() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      const diffMinutes = (end - start) / (1000 * 60) - breakTime;

      if (diffMinutes > 0) {
        const hours = Math.floor(diffMinutes / 60);
        const minutes = diffMinutes % 60;
        container.querySelector('#actual-work-time').textContent = `${hours}時間${minutes}分`;
      } else {
        container.querySelector('#actual-work-time').textContent = '0時間0分';
      }
    } else {
      container.querySelector('#actual-work-time').textContent = '0時間0分';
    }
  }

  // 中断記録の表示を更新
  function renderInterruptions() {
    const container_elem = container.querySelector('#saved-interruptions');
    if (savedInterruptions.length === 0) {
      container_elem.innerHTML = '';
      return;
    }

    container_elem.innerHTML = savedInterruptions.map((interruption, index) => `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; margin-bottom: 8px; background: var(--bg-card); border-radius: 6px; border: 1px solid var(--border);">
        <div style="display: flex; gap: 16px; align-items: center;">
          <span style="font-size: 12px; color: var(--text-muted);">理由:</span>
          <span style="font-size: 13px; color: var(--text);">${interruption.reason}</span>
          <span style="font-size: 12px; color: var(--text-muted);">時間:</span>
          <span style="font-size: 13px; color: var(--primary);">${interruption.time}分</span>
          ${interruption.details ? `<span style="font-size: 12px; color: var(--text-muted);">${interruption.details}</span>` : ''}
        </div>
        <button class="remove-interruption" data-index="${index}" style="background: transparent; color: var(--text-muted); border: none; padding: 4px; cursor: pointer; font-size: 12px;">削除</button>
      </div>
    `).join('');
  }

  // 作業状態に応じてボタンの有効/無効を切り替え
  function updateButtonStates() {
    const startBtn = container.querySelector('#btn-start-work');
    const interruptBtn = container.querySelector('#btn-interrupt-work');
    const endBtn = container.querySelector('#btn-end-work');

    switch (workStatus) {
      case 'not_started':
        startBtn.disabled = false;
        interruptBtn.disabled = true;
        endBtn.disabled = true;
        startBtn.textContent = '作業開始';
        break;
      case 'in_progress':
        startBtn.disabled = true;
        interruptBtn.disabled = false;
        endBtn.disabled = false;
        break;
      case 'interrupted':
        startBtn.disabled = false;
        interruptBtn.disabled = true;
        endBtn.disabled = false;
        startBtn.textContent = '作業再開';
        break;
      case 'completed':
        startBtn.disabled = true;
        interruptBtn.disabled = true;
        endBtn.disabled = true;
        break;
    }
  }

  // 初期化
  loadWorkItems();
  updateButtonStates();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#work-date').value = today;

  // 時間入力の変更監視
  container.querySelector('#start-time').addEventListener('change', updateActualWorkTime);
  container.querySelector('#end-time').addEventListener('change', updateActualWorkTime);
  container.querySelector('#break-time').addEventListener('input', updateActualWorkTime);

  // 中断追加ボタン
  container.querySelector('#btn-add-interruption').addEventListener('click', () => {
    const interruptionList = container.querySelector('#interruption-list');
    interruptionList.style.display = interruptionList.style.display === 'none' ? 'block' : 'none';
  });

  // 中断保存ボタン
  container.querySelector('#btn-save-interruption').addEventListener('click', () => {
    const reason = container.querySelector('#interruption-reason').value;
    const time = parseInt(container.querySelector('#interruption-time').value);
    const details = container.querySelector('#interruption-details').value;

    if (!reason || !time) {
      alert('中断理由と時間を入力してください。');
      return;
    }

    savedInterruptions.push({ reason, time, details });
    renderInterruptions();

    // フォームをクリア
    container.querySelector('#interruption-reason').value = '';
    container.querySelector('#interruption-time').value = '';
    container.querySelector('#interruption-details').value = '';
    container.querySelector('#interruption-list').style.display = 'none';
  });

  // 作業開始ボタン
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workDate = container.querySelector('#work-date').value;
    const workItem = container.querySelector('#work-item').value;
    const workLocation = container.querySelector('#work-location').value;
    const startTime = container.querySelector('#start-time').value;

    if (!workDate || !workItem || !workLocation || !startTime) {
      alert('必須項目を入力してください。');
      return;
    }

    const workRecord = {
      作業員ID: currentUser.id,
      作業日: new Date(workDate).toISOString(),
      作業開始時刻: new Date(`${workDate}T${startTime}`).toISOString(),
      作業終了時刻: null,
      作業時間: null,
      プロジェクト名: container.querySelector('#work-item option:checked').textContent.split(' - ')[0],
      作業場所: workLocation,
      作業種別: container.querySelector('#work-item option:checked').textContent.split(' - ')[1],
      作業内容: container.querySelector('#work-details').value,
      進捗状況: '作業中',
      備考: '',
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      currentWorkRecord = saved;
      workStatus = 'in_progress';
      updateButtonStates();
      alert('作業を開始しました。');
    }
  });

  // 作業中断ボタン
  container.querySelector('#btn-interrupt-work').addEventListener('click', () => {
    window.showScreen("scr-1778907238439");
  });

  // 作業終了ボタン
  container.querySelector('#btn-end-work').addEventListener('click', () => {
    window.showScreen("scr-1778907199709");
  });

  // 下書き保存ボタン
  container.querySelector('#btn-save-draft').addEventListener('click', async () => {
    const workDate = container.querySelector('#work-date').value;
    const workItem = container.querySelector('#work-item').value;
    const workLocation = container.querySelector('#work-location').value;

    if (!workDate || !workItem || !workLocation) {
      alert('作業日、作業項目、作業場所は必須です。');
      return;
    }

    const draftRecord = {
      作業員ID: currentUser.id,
      作業日: new Date(workDate).toISOString(),
      作業開始時刻: container.querySelector('#start-time').value ? new Date(`${workDate}T${container.querySelector('#start-time').value}`).toISOString() : null,
      作業終了時刻: container.querySelector('#end-time').value ? new Date(`${workDate}T${container.querySelector('#end-time').value}`).toISOString() : null,
      作業時間: null,
      プロジェクト名: container.querySelector('#work-item option:checked').textContent.split(' - ')[0],
      作業場所: workLocation,
      作業種別: container.querySelector('#work-item option:checked').textContent.split(' - ')[1],
      作業内容: container.querySelector('#work-details').value,
      進捗状況: '下書き',
      備考: '',
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, draftRecord);
    if (saved) {
      alert('下書きを保存しました。');
    }
  });

  // 中断記録削除
  container.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.remove-interruption');
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      savedInterruptions.splice(index, 1);
      renderInterruptions();
    }
  });
}

function(container, apiUrl, tables) {
  const anomalyTableIndex = 4; // 異常値検出ログテーブル
  const userTableIndex = 0; // ユーザーテーブル

  let currentAnomalies = [];
  let users = [];

  // ユーザー情報を取得
  async function loadUsers() {
    users = await window.aivicApi.list(userTableIndex) || [];
  }

  // ユーザー名を取得
  function getUserName(userId) {
    const user = users.find(u => u.id === userId);
    return user ? user.氏名 : 'Unknown';
  }

  // 重要度バッジのスタイル
  function getPriorityBadge(priority) {
    const colors = {
      '高': 'background: #ff4444; color: #fff;',
      '中': 'background: #ff6a00; color: #fff;',
      '低': 'background: #4a9eff; color: #fff;'
    };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${colors[priority] || colors['低']}">${priority}</span>`;
  }

  // ステータスバッジのスタイル
  function getStatusBadge(status) {
    const colors = {
      '未確認': 'background: #ff6a00; color: #fff;',
      '確認済み': 'background: #4a9eff; color: #fff;',
      '対応済み': 'background: #00c851; color: #fff;'
    };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${colors[status] || colors['未確認']}">${status}</span>`;
  }

  // 異常値一覧を再描画
  function renderAnomalies(anomalies) {
    const tbody = container.querySelector('#anomaly-tbody');
    tbody.innerHTML = anomalies.map(a => `
      <tr data-id="${a.id}" style="cursor: pointer;">
        <td><input type="checkbox" class="row-checkbox" data-id="${a.id}" style="accent-color: var(--primary);"></td>
        <td>${new Date(a.検出日時).toLocaleString()}</td>
        <td>${getUserName(a.ユーザーID)}</td>
        <td>${a.異常値種別}</td>
        <td>${a.検出項目}</td>
        <td>${a.検出値}</td>
        <td>${a.閾値}</td>
        <td>${getPriorityBadge(a.重要度)}</td>
        <td>${getStatusBadge(a.確認状況)}</td>
        <td>
          <button class="action-btn secondary approve-btn" data-id="${a.id}">承認</button>
          <button class="action-btn secondary reject-btn" data-id="${a.id}">却下</button>
        </td>
      </tr>
    `).join('');

    updateStatistics(anomalies);
  }

  // 統計情報を更新
  function updateStatistics(anomalies) {
    container.querySelector('#total-count').textContent = anomalies.length;
    container.querySelector('#unconfirmed-count').textContent = anomalies.filter(a => a.確認状況 === '未確認').length;
    container.querySelector('#long-work-count').textContent = anomalies.filter(a => a.異常値種別 === '長時間作業').length;
    container.querySelector('#interrupt-count').textContent = anomalies.filter(a => a.異常値種別 === '頻繁中断').length;
    container.querySelector('#overtime-count').textContent = anomalies.filter(a => a.異常値種別 === '工数超過').length;
  }

  // 詳細情報を表示
  function showDetail(anomaly) {
    const detailContent = container.querySelector('#detail-content');
    detailContent.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>検出対象:</strong> ${anomaly.検出対象テーブル}</div>
      <div style="margin-bottom: 8px;"><strong>作業員:</strong> ${getUserName(anomaly.ユーザーID)}</div>
      <div style="margin-bottom: 8px;"><strong>異常値種別:</strong> ${anomaly.異常値種別}</div>
      <div style="margin-bottom: 8px;"><strong>検出項目:</strong> ${anomaly.検出項目}</div>
      <div style="margin-bottom: 8px;"><strong>検出値:</strong> ${anomaly.検出値}</div>
      <div style="margin-bottom: 8px;"><strong>閾値:</strong> ${anomaly.閾値}</div>
      <div style="margin-bottom: 8px;"><strong>重要度:</strong> ${anomaly.重要度}</div>
      <div style="margin-bottom: 8px;"><strong>確認状況:</strong> ${anomaly.確認状況}</div>
      ${anomaly.対応メモ ? `<div style="margin-bottom: 8px;"><strong>対応メモ:</strong> ${anomaly.対応メモ}</div>` : ''}
      <div style="margin-bottom: 8px;"><strong>検出日時:</strong> ${new Date(anomaly.検出日時).toLocaleString()}</div>
      ${anomaly.確認日時 ? `<div><strong>確認日時:</strong> ${new Date(anomaly.確認日時).toLocaleString()}</div>` : ''}
    `;
  }

  // 進捗表示
  function showProgress() {
    const progressArea = container.querySelector('#progress-area');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressArea.classList.remove('hidden');

    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 20;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
        setTimeout(() => {
          progressArea.classList.add('hidden');
        }, 1000);
      }
      progressBar.style.width = progress + '%';
      progressText.textContent = Math.round(progress) + '%';
    }, 200);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['検出日時', '作業員', '異常値種別', '検出項目', '検出値', '閾値', '重要度', '確認状況', '対応メモ'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentAnomalies.map(a => [
        new Date(a.検出日時).toLocaleString(),
        getUserName(a.ユーザーID),
        a.異常値種別,
        a.検出項目,
        a.検出値,
        a.閾値,
        a.重要度,
        a.確認状況,
        a.対応メモ || ''
      ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `異常値検出結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    await loadUsers();
    currentAnomalies = await window.aivicApi.list(anomalyTableIndex) || [];
    renderAnomalies(currentAnomalies);
  }

  // 検索・フィルター
  function applyFilters() {
    const searchTerm = container.querySelector('#filter-search').value.toLowerCase();
    const statusFilter = container.querySelector('#filter-status').value;

    let filtered = currentAnomalies.filter(a => {
      const matchesSearch = !searchTerm || 
        getUserName(a.ユーザーID).toLowerCase().includes(searchTerm) ||
        a.異常値種別.toLowerCase().includes(searchTerm) ||
        a.検出項目.toLowerCase().includes(searchTerm);

      const matchesStatus = !statusFilter || a.確認状況 === statusFilter;

      return matchesSearch && matchesStatus;
    });

    renderAnomalies(filtered);
  }

  // 検出実行
  container.querySelector('#btn-detect').addEventListener('click', async () => {
    showProgress();

    // 実際の検出処理をシミュレート
    setTimeout(async () => {
      await loadData();
    }, 2000);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // フィルター
  container.querySelector('#filter-search').addEventListener('input', applyFilters);
  container.querySelector('#filter-status').addEventListener('change', applyFilters);

  // 全選択
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括承認
  container.querySelector('#btn-bulk-approve').addEventListener('click', async () => {
    const selected = Array.from(container.querySelectorAll('.row-checkbox:checked')).map(cb => cb.dataset.id);
    if (selected.length === 0) {
      alert('承認する項目を選択してください');
      return;
    }

    for (const id of selected) {
      await window.aivicApi.update(anomalyTableIndex, id, {
        確認状況: '対応済み',
        確認日時: new Date().toISOString(),
        確認者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
      });
    }

    await loadData();
  });

  // 一括却下
  container.querySelector('#btn-bulk-reject').addEventListener('click', async () => {
    const selected = Array.from(container.querySelectorAll('.row-checkbox:checked')).map(cb => cb.dataset.id);
    if (selected.length === 0) {
      alert('却下する項目を選択してください');
      return;
    }

    for (const id of selected) {
      await window.aivicApi.update(anomalyTableIndex, id, {
        確認状況: '確認済み',
        確認日時: new Date().toISOString(),
        確認者ID: 'current-user-id'
      });
    }

    await loadData();
  });

  // ルール保存
  container.querySelector('#btn-save-rules').addEventListener('click', () => {
    const rules = {
      longWorkThreshold: container.querySelector('#long-work-threshold').value,
      interruptThreshold: container.querySelector('#interrupt-threshold').value,
      overtimeThreshold: container.querySelector('#overtime-threshold').value,
      excludeWeekends: container.querySelector('#exclude-weekends').checked
    };

    localStorage.setItem('anomalyDetectionRules', JSON.stringify(rules));
    alert('検出ルールを保存しました');
  });

  // 行レベル操作
  container.addEventListener('click', async (e) => {
    const approveBtn = e.target.closest('.approve-btn');
    const rejectBtn = e.target.closest('.reject-btn');
    const row = e.target.closest('tr[data-id]');

    if (approveBtn) {
      const id = approveBtn.dataset.id;
      await window.aivicApi.update(anomalyTableIndex, id, {
        確認状況: '対応済み',
        確認日時: new Date().toISOString(),
        確認者ID: 'current-user-id'
      });
      await loadData();
    } else if (rejectBtn) {
      const id = rejectBtn.dataset.id;
      await window.aivicApi.update(anomalyTableIndex, id, {
        確認状況: '確認済み',
        確認日時: new Date().toISOString(),
        確認者ID: 'current-user-id'
      });
      await loadData();
    } else if (row && !e.target.closest('button') && !e.target.closest('input')) {
      const anomaly = currentAnomalies.find(a => a.id === row.dataset.id);
      if (anomaly) {
        showDetail(anomaly);
      }
    }
  });

  // 保存されたルールを読み込み
  const savedRules = localStorage.getItem('anomalyDetectionRules');
  if (savedRules) {
    const rules = JSON.parse(savedRules);
    container.querySelector('#long-work-threshold').value = rules.longWorkThreshold || 10;
    container.querySelector('#interrupt-threshold').value = rules.interruptThreshold || 5;
    container.querySelector('#overtime-threshold').value = rules.overtimeThreshold || 150;
    container.querySelector('#exclude-weekends').checked = rules.excludeWeekends || false;
  }

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let currentRecordId = null;
  let originalData = null;

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector("#select-work-item");
    if (workItems) {
      workItems.forEach(item => {
        const option = document.createElement("option");
        option.value = item.id;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
    }
  }

  // 作業記録一覧を読み込み
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録
    const select = container.querySelector("#select-record");
    if (records) {
      records.forEach(record => {
        const option = document.createElement("option");
        option.value = record.id;
        const date = new Date(record.作業日).toLocaleDateString();
        option.textContent = `${date} - ${record.プロジェクト名} (${record.進捗状況})`;
        select.appendChild(option);
      });
    }
  }

  // 時間計算
  function calculateDuration() {
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = container.querySelector("#input-break-time").value;

    if (!startTime || !endTime) {
      container.querySelector("#display-work-duration").textContent = "0分";
      container.querySelector("#display-break-duration").textContent = "0分";
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);
    let totalMinutes = (end - start) / (1000 * 60);

    let breakMinutes = 0;
    if (breakTime) {
      // 簡易的に30分の中断として計算
      breakMinutes = 30;
    }

    const workMinutes = Math.max(0, totalMinutes - breakMinutes);

    container.querySelector("#display-break-duration").textContent = `${breakMinutes}分`;
    container.querySelector("#display-work-duration").textContent = `${workMinutes}分`;

    // 異常値チェック
    checkAnomalies(workMinutes, breakMinutes);
  }

  // 異常値チェック
  function checkAnomalies(workMinutes, breakMinutes) {
    const warnings = [];

    if (workMinutes > 480) { // 8時間超
      warnings.push("作業時間が8時間を超えています");
    }
    if (workMinutes > 0 && workMinutes < 30) { // 30分未満
      warnings.push("作業時間が短すぎます");
    }
    if (breakMinutes > 120) { // 2時間超の中断
      warnings.push("中断時間が長すぎます");
    }

    const warningPanel = container.querySelector("#warning-panel");
    const warningContent = container.querySelector("#warning-content");

    if (warnings.length > 0) {
      warningContent.innerHTML = warnings.map(w => `• ${w}`).join('<br>');
      warningPanel.style.display = "block";
    } else {
      warningPanel.style.display = "none";
    }
  }

  // 記録選択時の処理
  container.querySelector("#select-record").addEventListener("change", async function() {
    const recordId = this.value;
    if (!recordId) {
      currentRecordId = null;
      originalData = null;
      container.querySelector("#original-data-panel").style.display = "none";
      return;
    }

    currentRecordId = recordId;
    const records = await window.aivicApi.list(1);
    if (records) {
      const record = records.find(r => r.id === recordId);
      if (record) {
        originalData = { ...record };

        // フォームに既存データを設定
        const workDate = new Date(record.作業日);
        container.querySelector("#input-work-date").value = workDate.toISOString().split('T')[0];

        const startTime = new Date(record.作業開始時刻);
        container.querySelector("#input-start-time").value = startTime.toTimeString().slice(0, 5);

        if (record.作業終了時刻) {
          const endTime = new Date(record.作業終了時刻);
          container.querySelector("#input-end-time").value = endTime.toTimeString().slice(0, 5);
        }

        container.querySelector("#input-project").value = record.プロジェクト名 || "";
        container.querySelector("#input-location").value = record.作業場所 || "";
        container.querySelector("#select-work-type").value = record.作業種別 || "";
        container.querySelector("#textarea-content").value = record.作業内容 || "";

        // 修正前データ表示
        const originalPanel = container.querySelector("#original-data-panel");
        const originalContent = container.querySelector("#original-data-content");
        originalContent.innerHTML = `
          <div><strong>作業日:</strong> ${workDate.toLocaleDateString()}</div>
          <div><strong>開始:</strong> ${startTime.toLocaleTimeString()}</div>
          <div><strong>終了:</strong> ${record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString() : '未設定'}</div>
          <div><strong>プロジェクト:</strong> ${record.プロジェクト名}</div>
          <div><strong>場所:</strong> ${record.作業場所}</div>
          <div><strong>種別:</strong> ${record.作業種別}</div>
        `;
        originalPanel.style.display = "block";

        calculateDuration();
      }
    }
  });

  // 時間入力時の自動計算
  container.querySelector("#input-start-time").addEventListener("change", calculateDuration);
  container.querySelector("#input-end-time").addEventListener("change", calculateDuration);
  container.querySelector("#input-break-time").addEventListener("change", calculateDuration);

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", function() {
    container.querySelectorAll("input, select, textarea").forEach(el => {
      if (el.type === "checkbox" || el.type === "radio") {
        el.checked = false;
      } else {
        el.value = "";
      }
    });
    currentRecordId = null;
    originalData = null;
    container.querySelector("#original-data-panel").style.display = "none";
    container.querySelector("#warning-panel").style.display = "none";
    calculateDuration();
  });

  // 修正保存ボタン
  container.querySelector("#btn-save").addEventListener("click", async function() {
    if (!currentRecordId) {
      alert("修正対象の記録を選択してください");
      return;
    }

    const reason = container.querySelector("#textarea-reason").value.trim();
    if (!reason) {
      alert("修正理由を入力してください");
      return;
    }

    const workDate = container.querySelector("#input-work-date").value;
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;

    if (!workDate || !startTime) {
      alert("作業日と開始時刻は必須です");
      return;
    }

    const updateData = {
      作業日: new Date(workDate).toISOString(),
      作業開始時刻: new Date(`${workDate}T${startTime}`).toISOString(),
      作業終了時刻: endTime ? new Date(`${workDate}T${endTime}`).toISOString() : null,
      プロジェクト名: container.querySelector("#input-project").value,
      作業場所: container.querySelector("#input-location").value,
      作業種別: container.querySelector("#select-work-type").value,
      作業内容: container.querySelector("#textarea-content").value,
      更新日時: new Date().toISOString()
    };

    // 作業時間を計算
    if (updateData.作業終了時刻) {
      const start = new Date(updateData.作業開始時刻);
      const end = new Date(updateData.作業終了時刻);
      updateData.作業時間 = Math.floor((end - start) / (1000 * 60));
    }

    const result = await window.aivicApi.update(1, currentRecordId, updateData);
    if (result) {
      alert("修正が保存されました");
      // 履歴画面に遷移
      window.showScreen("scr-1778907145716");
    }
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", function() {
    window.showScreen("scr-1778907133295");
  });

  // 履歴一覧ボタン
  container.querySelector("#btn-history").addEventListener("click", function() {
    window.showScreen("scr-1778907145716");
  });

  // 初期化
  loadWorkItems();
  loadWorkRecords();
}

function(container, apiUrl, tables) {
  let selectedUrgency = '';
  let selectedPhotos = [];

  // 現在日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#incident-datetime').value = now.toISOString().slice(0, 16);

  // 作業項目マスタを読み込み（テーブルインデックス3）
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3);
    const select = container.querySelector('#work-item');
    if (workItems) {
      workItems.forEach(item => {
        const option = document.createElement('option');
        option.value = item.id;
        option.textContent = `${item.作業項目コード || ''} - ${item.作業項目名 || ''}`;
        select.appendChild(option);
      });
    }
  }

  // 報告者名を設定（ログインユーザー情報から）
  async function loadReporter() {
    const users = await window.aivicApi.list(0);
    if (users && users.length > 0) {
      // 最初のユーザーを現在のログインユーザーとして扱う
      container.querySelector('#reporter-name').value = users[0].氏名 || '';
    }
  }

  // 緊急度ボタンのイベント
  container.querySelectorAll('.urgency-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      // 全ボタンをリセット
      container.querySelectorAll('.urgency-btn').forEach(b => {
        b.style.background = 'transparent';
      });
      // 選択されたボタンを強調
      btn.style.background = btn.style.borderColor;
      btn.style.color = '#fff';
      selectedUrgency = btn.dataset.level;
    });
  });

  // 写真選択
  container.querySelector('#photo-btn').addEventListener('click', () => {
    container.querySelector('#photo-input').click();
  });

  container.querySelector('#photo-input').addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    selectedPhotos = files;

    // 枚数表示
    container.querySelector('#photo-count').textContent = `${files.length}枚選択`;

    // プレビュー表示
    const preview = container.querySelector('#photo-preview');
    preview.innerHTML = '';

    files.forEach((file, index) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = document.createElement('img');
        img.src = e.target.result;
        img.style.cssText = 'width: 80px; height: 80px; object-fit: cover; border-radius: 4px; border: 1px solid rgba(255,255,255,0.18);';
        preview.appendChild(img);
      };
      reader.readAsDataURL(file);
    });
  });

  // 下書き保存
  container.querySelector('#btn-draft').addEventListener('click', async () => {
    const reportData = {
      緊急度: selectedUrgency,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#incident-datetime').value,
      発生場所: container.querySelector('#incident-location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#incident-content').value,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      写真枚数: selectedPhotos.length,
      状態: '下書き',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    // 緊急報告用の新しいテーブルとして保存（仮想テーブルインデックス99）
    const saved = await window.aivicApi.save(99, reportData);
    if (saved) {
      alert('下書きを保存しました');
    }
  });

  // 即座に報告
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    // 必須項目チェック
    if (!selectedUrgency) {
      alert('緊急度を選択してください');
      return;
    }
    if (!container.querySelector('#report-type').value) {
      alert('報告種別を選択してください');
      return;
    }
    if (!container.querySelector('#incident-content').value.trim()) {
      alert('緊急事態内容を入力してください');
      return;
    }

    const reportData = {
      緊急度: selectedUrgency,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#incident-datetime').value,
      発生場所: container.querySelector('#incident-location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#incident-content').value,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      写真枚数: selectedPhotos.length,
      状態: '報告済み',
      報告日時: new Date().toISOString(),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(99, reportData);
    if (saved) {
      alert('緊急報告を送信しました');
      // フォームをリセット
