function(container, apiUrl, tables) {
  let currentRecordId = null;
  let workRecords = [];
  let workItems = [];

  // 時間計算関数
  function calculateDuration(startTime, endTime) {
    if (!startTime || !endTime) return '';
    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);
    if (end <= start) return '';
    const diffMs = end - start;
    const hours = Math.floor(diffMs / (1000 * 60 * 60));
    const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
    return `${hours}時間${minutes}分`;
  }

  function calculateMinutes(startTime, endTime) {
    if (!startTime || !endTime) return 0;
    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);
    if (end <= start) return 0;
    return Math.floor((end - start) / (1000 * 60));
  }

  // 異常値チェック
  function checkAnomalies(workMinutes, breakMinutes) {
    const warnings = [];
    const netMinutes = workMinutes - (breakMinutes || 0);

    if (workMinutes > 12 * 60) { // 12時間超過
      warnings.push('作業時間が12時間を超えています');
    }
    if (netMinutes > 10 * 60) { // 正味10時間超過
      warnings.push('正味作業時間が10時間を超えています');
    }
    if (breakMinutes > workMinutes * 0.5) { // 中断時間が作業時間の50%超過
      warnings.push('中断時間が作業時間の50%を超えています');
    }

    const warningArea = container.querySelector('#warning-area');
    const warningMessage = container.querySelector('#warning-message');

    if (warnings.length > 0) {
      warningMessage.textContent = warnings.join('、');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // 時間変更時の自動計算
  function updateTimeCalculation() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    const workDuration = calculateDuration(startTime, endTime);
    const workMinutes = calculateMinutes(startTime, endTime);
    const netMinutes = workMinutes - breakTime;

    container.querySelector('#display-work-duration').value = workDuration;

    if (netMinutes >= 0) {
      const netHours = Math.floor(netMinutes / 60);
      const netMins = netMinutes % 60;
      container.querySelector('#display-net-duration').value = `${netHours}時間${netMins}分`;
    } else {
      container.querySelector('#display-net-duration').value = '計算エラー';
    }

    checkAnomalies(workMinutes, breakTime);
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録一覧を取得
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];

      // 作業項目マスタを取得
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      // 修正対象作業記録のドロップダウンを更新
      const selectWorkRecord = container.querySelector('#select-work-record');
      selectWorkRecord.innerHTML = '<option value="">選択してください</option>' +
        workRecords.filter(r => r.承認状態 !== '承認済み').map(record => 
          `<option value="${record.作業記録ID}">${record.作業日?.split('T')[0] || ''} - ${record.プロジェクト名 || ''} (${record.作業種別 || ''})</option>`
        ).join('');

      // 作業項目ドロップダウンを更新
      const selectWorkItem = container.querySelector('#select-work-item');
      selectWorkItem.innerHTML = '<option value="">選択してください</option>' +
        workItems.filter(item => item.有効フラグ).map(item => 
          `<option value="${item.作業項目ID}">${item.作業項目名}</option>`
        ).join('');

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 作業記録選択時の処理
  container.querySelector('#select-work-record').addEventListener('change', function() {
    const recordId = this.value;
    currentRecordId = recordId;

    if (!recordId) {
      // フォームクリア
      container.querySelector('#input-work-date').value = '';
      container.querySelector('#input-start-time').value = '';
      container.querySelector('#input-end-time').value = '';
      container.querySelector('#input-break-time').value = '';
      container.querySelector('#input-work-detail').value = '';
      container.querySelector('#input-correction-reason').value = '';
      container.querySelector('#select-work-item').value = '';
      container.querySelector('#display-work-duration').value = '';
      container.querySelector('#display-net-duration').value = '';
      container.querySelector('#warning-area').style.display = 'none';
      return;
    }

    const record = workRecords.find(r => r.作業記録ID === recordId);
    if (record) {
      // フォームに既存データを設定
      const workDate = record.作業日 ? new Date(record.作業日).toISOString().split('T')[0] : '';
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toTimeString().slice(0, 5) : '';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toTimeString().slice(0, 5) : '';

      container.querySelector('#input-work-date').value = workDate;
      container.querySelector('#input-start-time').value = startTime;
      container.querySelector('#input-end-time').value = endTime;
      container.querySelector('#input-break-time').value = '0';
      container.querySelector('#input-work-detail').value = record.作業内容 || '';
      container.querySelector('#select-work-item').value = record.作業種別 || '';

      updateTimeCalculation();
    }
  });

  // 元データ参照ボタン
  container.querySelector('#btn-load-record').addEventListener('click', function() {
    if (!currentRecordId) {
      alert('修正対象の作業記録を選択してください');
      return;
    }

    const record = workRecords.find(r => r.作業記録ID === currentRecordId);
    if (record) {
      const details = [
        `作業日: ${record.作業日?.split('T')[0] || ''}`,
        `プロジェクト: ${record.プロジェクト名 || ''}`,
        `作業場所: ${record.作業場所 || ''}`,
        `作業種別: ${record.作業種別 || ''}`,
        `進捗状況: ${record.進捗状況 || ''}`,
        `承認状態: ${record.承認状態 || ''}`,
        `作業内容: ${record.作業内容 || ''}`
      ].join('\n');

      alert(`元データ詳細:\n\n${details}`);
    }
  });

  // 時間入力の変更監視
  container.querySelector('#input-start-time').addEventListener('change', updateTimeCalculation);
  container.querySelector('#input-end-time').addEventListener('change', updateTimeCalculation);
  container.querySelector('#input-break-time').addEventListener('input', updateTimeCalculation);

  // 修正完了ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!currentRecordId) {
      alert('修正対象の作業記録を選択してください');
      return;
    }

    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;
    const workDetail = container.querySelector('#input-work-detail').value.trim();
    const correctionReason = container.querySelector('#input-correction-reason').value.trim();
    const workItemId = container.querySelector('#select-work-item').value;

    if (!startTime || !endTime) {
      alert('開始時刻と終了時刻を入力してください');
      return;
    }

    if (!correctionReason) {
      alert('修正理由を入力してください');
      return;
    }

    if (!workDetail) {
      alert('作業内容詳細を入力してください');
      return;
    }

    const workMinutes = calculateMinutes(startTime, endTime);
    if (workMinutes <= 0) {
      alert('終了時刻は開始時刻より後に設定してください');
      return;
    }

    try {
      // 作業記録を更新
      const workDate = container.querySelector('#input-work-date').value;
      const startDateTime = new Date(`${workDate}T${startTime}`).toISOString();
      const endDateTime = new Date(`${workDate}T${endTime}`).toISOString();

      const updateData = {
        作業開始時刻: startDateTime,
        作業終了時刻: endDateTime,
        作業時間: workMinutes - breakTime,
        作業内容: workDetail,
        承認状態: '未承認',
        更新日時: new Date().toISOString()
      };

      const updated = await window.aivicApi.update(1, currentRecordId, updateData);

      if (updated) {
        // 異常値検出ログを記録（警告が表示されている場合）
        const warningArea = container.querySelector('#warning-area');
        if (warningArea.style.display !== 'none') {
          const warningMessage = container.querySelector('#warning-message').textContent;
          await window.aivicApi.save(4, {
            異常値検出ログID: crypto.randomUUID(),
            検出対象テーブル: '作業記録',
            検出対象レコードID: currentRecordId,
            ユーザーID: 'current-user', // 実際の実装では現在のユーザーIDを使用
            異常値種別: '工数修正時異常値',
            検出項目: '作業時間',
            検出値: `${Math.floor(workMinutes/60)}時間${workMinutes%60}分`,
            閾値: '12時間',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: false,
            対応メモ: `修正理由: ${correctionReason}`,
            検出日時: new Date().toISOString(),
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          });
        }

        alert('工数修正が完了しました');
        window.showScreen("scr-1778907367889");
      } else {
        alert('修正に失敗しました');
      }
    } catch (error) {
      console.error('修正エラー:', error);
      alert('修正中にエラーが発生しました');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    if (confirm('修正内容を破棄して戻りますか？')) {
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let workers = [];
  let workItems = [];

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録データ
      const workRecords = await window.aivicApi.list(1) || [];
      currentData = workRecords;

      // ユーザー（作業員）データ
      workers = await window.aivicApi.list(0) || [];

      // 作業項目マスタ
      workItems = await window.aivicApi.list(3) || [];

      // セレクトボックスの初期化
      populateWorkerSelect();
      populateWorkItemSelect();

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 作業員セレクトボックスの設定
  function populateWorkerSelect() {
    const select = container.querySelector('#select-worker');
    select.innerHTML = '';
    workers.forEach(worker => {
      const option = document.createElement('option');
      option.value = worker.id;
      option.textContent = worker.氏名 || worker.ユーザー名 || 'Unknown';
      select.appendChild(option);
    });
  }

  // 作業項目セレクトボックスの設定
  function populateWorkItemSelect() {
    const select = container.querySelector('#select-work-item');
    select.innerHTML = '';
    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.id;
      option.textContent = item.作業項目名 || 'Unknown';
      select.appendChild(option);
    });
  }

  // データフィルタリング
  function filterData() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const location = container.querySelector('#select-location').value;
    const selectedWorkers = Array.from(container.querySelector('#select-worker').selectedOptions).map(opt => opt.value);
    const selectedWorkItems = Array.from(container.querySelector('#select-work-item').selectedOptions).map(opt => opt.value);
    const includeAnomaly = container.querySelector('#check-include-anomaly').checked;
    const includeInterruption = container.querySelector('#check-include-interruption').checked;

    let filtered = [...currentData];

    // 期間フィルタ
    if (startDate) {
      filtered = filtered.filter(record => {
        const workDate = new Date(record.作業日);
        return workDate >= new Date(startDate);
      });
    }
    if (endDate) {
      filtered = filtered.filter(record => {
        const workDate = new Date(record.作業日);
        return workDate <= new Date(endDate);
      });
    }

    // 場所フィルタ
    if (location) {
      filtered = filtered.filter(record => record.作業場所 === location);
    }

    // 作業員フィルタ
    if (selectedWorkers.length > 0) {
      filtered = filtered.filter(record => selectedWorkers.includes(record.作業員ID));
    }

    // 進捗状況フィルタ（中断記録の扱い）
    if (!includeInterruption) {
      filtered = filtered.filter(record => record.進捗状況 !== '中断');
    }

    return filtered;
  }

  // プレビューテーブル更新
  function updatePreview() {
    const filteredData = filterData();
    const tbody = container.querySelector('#preview-tbody');
    const countElement = container.querySelector('#data-count');

    countElement.textContent = `対象件数: ${filteredData.length}件`;

    if (filteredData.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">条件に該当するデータがありません</td></tr>';
      container.querySelector('#btn-export').disabled = true;
      return;
    }

    // 最大10件まで表示
    const displayData = filteredData.slice(0, 10);
    tbody.innerHTML = displayData.map(record => {
      const worker = workers.find(w => w.id === record.作業員ID);
      const workerName = worker ? (worker.氏名 || worker.ユーザー名) : 'Unknown';
      const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}h${record.作業時間 % 60}m` : '';

      return `
        <tr style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${workDate}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${workerName}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.作業場所 || ''}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.作業種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${workTime}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${record.進捗状況 || ''}</td>
        </tr>
      `;
    }).join('');

    if (filteredData.length > 10) {
      tbody.innerHTML += `<tr><td colspan="6" style="padding: 8px 10px; text-align: center; color: var(--text-muted); font-size: 11px;">他 ${filteredData.length - 10} 件...</td></tr>`;
    }

    container.querySelector('#btn-export').disabled = false;
  }

  // 条件プレビュー更新
  function updateConditionPreview() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const location = container.querySelector('#select-location').value;
    const selectedWorkers = Array.from(container.querySelector('#select-worker').selectedOptions);
    const selectedWorkItems = Array.from(container.querySelector('#select-work-item').selectedOptions);
    const includeAnomaly = container.querySelector('#check-include-anomaly').checked;
    const includeInterruption = container.querySelector('#check-include-interruption').checked;
    const format = container.querySelector('#select-format').value;

    let conditions = [];

    if (startDate || endDate) {
      const period = startDate && endDate ? `${startDate} ～ ${endDate}` : 
                    startDate ? `${startDate} 以降` : `${endDate} まで`;
      conditions.push(`期間: ${period}`);
    }

    if (location) {
      conditions.push(`作業場所: ${location}`);
    }

    if (selectedWorkers.length > 0) {
      const workerNames = selectedWorkers.map(opt => opt.textContent).join(', ');
      conditions.push(`作業員: ${workerNames}`);
    }

    if (selectedWorkItems.length > 0) {
      const itemNames = selectedWorkItems.map(opt => opt.textContent).join(', ');
      conditions.push(`作業項目: ${itemNames}`);
    }

    conditions.push(`異常値データ: ${includeAnomaly ? '含む' : '除外'}`);
    conditions.push(`中断記録: ${includeInterruption ? '含む' : '除外'}`);
    conditions.push(`出力形式: ${format.toUpperCase()}`);

    const previewElement = container.querySelector('#condition-preview');
    previewElement.innerHTML = conditions.length > 0 ? conditions.join('<br>') : '条件が設定されていません';
  }

  // CSVエクスポート
  function exportData() {
    const filteredData = filterData();
    const format = container.querySelector('#select-format').value;

    if (filteredData.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    // CSVヘッダー
    const headers = ['作業日', '作業員名', '作業場所', '作業種別', '作業内容', '作業時間(分)', '進捗状況', '承認状態'];

    // CSVデータ作成
    const csvData = filteredData.map(record => {
      const worker = workers.find(w => w.id === record.作業員ID);
      const workerName = worker ? (worker.氏名 || worker.ユーザー名) : '';
      const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '';

      return [
        workDate,
        workerName,
        record.作業場所 || '',
        record.作業種別 || '',
        record.作業内容 || '',
        record.作業時間 || '',
        record.進捗状況 || '',
        record.承認状態 || ''
      ].map(field => {
        const str = String(field);
        return str.includes(',') || str.includes('\n') || str.includes('"') ? `"${str.replace(/"/g, '""')}"` : str;
      });
    });

    // CSV文字列作成
    const csvContent = '\uFEFF' + [headers, ...csvData].map(row => row.join(',')).join('\n');

    // ダウンロード
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `工数記録データ_${new Date().toISOString().split('T')[0]}.${format}`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#input-start-date').value = '';
    container.querySelector('#input-end-date').value = '';
    container.querySelector('#select-location').value = '';
    container.querySelector('#select-worker').selectedIndex = -1;
    container.querySelector('#select-work-item').selectedIndex = -1;
    container.querySelector('#check-include-anomaly').checked = false;
    container.querySelector('#check-include-interruption').checked = false;
    container.querySelector('#select-format').value = 'csv';

    updateConditionPreview();
    container.querySelector('#preview-tbody').innerHTML = '<tr><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">条件を設定してプレビューを表示してください</td></tr>';
    container.querySelector('#data-count').textContent = '対象件数: -';
    container.querySelector('#btn-export').disabled = true;
  }

  // イベントリスナー設定
  container.querySelector('#btn-preview').addEventListener('click', () => {
    updateConditionPreview();
    updatePreview();
  });

  container.querySelector('#btn-clear').addEventListener('click', clearConditions);

  container.querySelector('#btn-save-condition').addEventListener('click', () => {
    // 条件保存機能（実装省略）
    alert('条件を保存しました');
  });

  container.querySelector('#btn-export').addEventListener('click', exportData);

  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  // 初期化
  loadInitialData();
  updateConditionPreview();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#records-tbody");
  const detailArea = container.querySelector("#detail-area");
  let currentRecordId = null;
  let allRecords = [];
  let allUsers = [];
  let allInterruptions = [];
  let allAnomalies = [];

  // ユーザー情報とその他データを取得
  async function loadAllData() {
    try {
      allUsers = await window.aivicApi.list(0) || []; // ユーザー
      allRecords = await window.aivicApi.list(1) || []; // 作業記録
      allInterruptions = await window.aivicApi.list(2) || []; // 中断記録
      allAnomalies = await window.aivicApi.list(4) || []; // 異常値検出ログ
    } catch (error) {
      console.error("データ取得エラー:", error);
      allUsers = tables[0]?.records || [];
      allRecords = tables[1]?.records || [];
      allInterruptions = tables[2]?.records || [];
      allAnomalies = tables[4]?.records || [];
    }
  }

  // ユーザー名を取得
  function getUserName(userId) {
    const user = allUsers.find(u => u.id === userId);
    return user ? user.氏名 : "不明";
  }

  // 時間フォーマット（分を時:分に変換）
  function formatMinutes(minutes) {
    if (!minutes) return "-";
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return "-";
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', { 
      month: '2-digit', 
      day: '2-digit', 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return "-";
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 異常値チェック
  function hasAnomaly(recordId) {
    return allAnomalies.some(a => a.検出対象レコードID === recordId && a.確認状況 === "未確認");
  }

  // 中断時間合計を計算
  function getTotalInterruptionTime(recordId) {
    const interruptions = allInterruptions.filter(i => i.作業記録ID === recordId);
    return interruptions.reduce((total, i) => total + (i.中断時間 || 0), 0);
  }

  // 承認状態バッジ
  function getStatusBadge(status) {
    const colors = {
      "未承認": "background: #ffc107; color: #000;",
      "承認済み": "background: #28a745; color: #fff;",
      "差し戻し": "background: #dc3545; color: #fff;"
    };
    const style = colors[status] || "background: var(--bg-card); color: var(--text);";
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${style}">${status}</span>`;
  }

  // テーブル再描画
  function renderRows(records) {
    tbody.innerHTML = records.map(record => {
      const userName = getUserName(record.作業員ID);
      const interruptionTime = getTotalInterruptionTime(record.id);
      const anomalyIcon = hasAnomaly(record.id) ? 
        '<span style="color: #ff6a00; font-size: 14px;" title="異常値検出">⚠️</span>' : '-';

      return `
        <tr data-id="${record.id}" style="cursor: pointer; height: 36px;">
          <td style="padding: 6px 10px; font-size: 13px;">${formatDate(record.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${userName}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${record.プロジェクト名 || "-"}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${record.作業場所 || "-"}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatDateTime(record.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatDateTime(record.作業終了時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatMinutes(record.作業時間)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatMinutes(interruptionTime)}</td>
          <td style="padding: 6px 10px;">${getStatusBadge(record.承認状態)}</td>
          <td style="padding: 6px 10px; text-align: center;">${anomalyIcon}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary view-detail-btn" data-id="${record.id}" style="font-size: 12px; padding: 4px 8px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 詳細表示
  function showDetail(recordId) {
    const record = allRecords.find(r => r.id === recordId);
    if (!record) return;

    currentRecordId = recordId;

    // 作業内容詳細
    container.querySelector("#detail-content").textContent = record.作業内容 || "-";
    container.querySelector("#detail-memo").textContent = record.備考 || "-";

    // 中断記録
    const interruptions = allInterruptions.filter(i => i.作業記録ID === recordId);
    const interruptionTable = container.querySelector("#interruption-table");

    if (interruptions.length > 0) {
      interruptionTable.innerHTML = `
        <div style="background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; padding: 8px;">
          ${interruptions.map(i => `
            <div style="margin-bottom: 6px; padding-bottom: 6px; border-bottom: 1px solid rgba(255,255,255,0.1);">
              <div style="font-size: 12px; color: var(--text);">
                <strong>${i.中断理由区分}</strong> (${formatMinutes(i.中断時間)})
              </div>
              <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
                ${formatDateTime(i.中断開始日時)} - ${formatDateTime(i.中断終了日時)}
              </div>
              ${i.中断理由詳細 ? `<div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${i.中断理由詳細}</div>` : ''}
            </div>
          `).join("")}
        </div>
      `;
    } else {
      interruptionTable.innerHTML = '<div style="font-size: 12px; color: var(--text-muted);">中断記録なし</div>';
    }

    // 承認状態に応じてボタンの表示制御
    const approveBtn = container.querySelector("#btn-approve");
    const rejectBtn = container.querySelector("#btn-reject");

    if (record.承認状態 === "承認済み") {
      approveBtn.style.display = "none";
      rejectBtn.textContent = "承認取消";
    } else {
      approveBtn.style.display = "inline-block";
      rejectBtn.textContent = "差し戻し";
    }

    detailArea.classList.remove("hidden");
  }

  // 検索・フィルタ
  function filterRecords() {
    const dateFilter = container.querySelector("#filter-date").value;
    const workerFilter = container.querySelector("#filter-worker").value.toLowerCase();
    const statusFilter = container.querySelector("#filter-status").value;

    let filtered = allRecords;

    if (dateFilter) {
      filtered = filtered.filter(r => {
        const recordDate = new Date(r.作業日).toISOString().split('T')[0];
        return recordDate === dateFilter;
      });
    }

    if (workerFilter) {
      filtered = filtered.filter(r => {
        const userName = getUserName(r.作業員ID).toLowerCase();
        return userName.includes(workerFilter);
      });
    }

    if (statusFilter) {
      filtered = filtered.filter(r => r.承認状態 === statusFilter);
    }

    renderRows(filtered);
  }

  // 承認処理
  async function approveRecord(recordId) {
    try {
      await window.aivicApi.update(1, recordId, {
        承認状態: "承認済み",
        承認日時: new Date().toISOString()
      });

      // データを再読み込みして表示更新
      await loadAllData();
      filterRecords();

      // 詳細表示も更新
      if (currentRecordId === recordId) {
        showDetail(recordId);
      }
    } catch (error) {
      console.error("承認処理エラー:", error);
    }
  }

  // 差し戻し処理
  async function rejectRecord(recordId) {
    const record = allRecords.find(r => r.id === recordId);
    if (!record) return;

    try {
      if (record.承認状態 === "承認済み") {
        // 承認取消
        await window.aivicApi.update(1, recordId, {
          承認状態: "未承認",
          承認日時: null
        });
      } else {
        // 差し戻し
        await window.aivicApi.update(1, recordId, {
          承認状態: "差し戻し"
        });
      }

      // データを再読み込みして表示更新
      await loadAllData();
      filterRecords();

      // 詳細表示も更新
      if (currentRecordId === recordId) {
        showDetail(recordId);
      }
    } catch (error) {
      console.error("差し戻し処理エラー:", error);
    }
  }

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", filterRecords);

  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    detailArea.classList.add("hidden");
    currentRecordId = null;
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    const viewDetailBtn = e.target.closest(".view-detail-btn");
    if (viewDetailBtn) {
      showDetail(viewDetailBtn.dataset.id);
      return;
    }

    const editBtn = e.target.closest("#btn-edit-record");
    if (editBtn && currentRecordId) {
      window.showScreen("scr-1778907343735");
      return;
    }

    const approveBtn = e.target.closest("#btn-approve");
    if (approveBtn && currentRecordId) {
      if (confirm("この記録を承認しますか？")) {
        await approveRecord(currentRecordId);
      }
      return;
    }

    const rejectBtn = e.target.closest("#btn-reject");
    if (rejectBtn && currentRecordId) {
      const record = allRecords.find(r => r.id === currentRecordId);
      const action = record?.承認状態 === "承認済み" ? "承認を取り消し" : "差し戻し";
      if (confirm(`この記録を${action}ますか？`)) {
        await rejectRecord(currentRecordId);
      }
      return;
    }
  });

  // 初期化
  loadAllData().then(() => {
    renderRows(allRecords);
  });
}

function(container, apiUrl, tables) {
  let currentBreaks = [];
  let currentUser = null;

  // 現在のユーザー情報を取得
  async function loadCurrentUser() {
    const users = await window.aivicApi.list(0);
    if (users && users.length > 0) {
      currentUser = users[0];
      container.querySelector("#worker-name").textContent = currentUser.氏名 || currentUser.ユーザー名 || "-";
    }
  }

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3);
    const select = container.querySelector("#work-item");
    select.innerHTML = '<option value="">選択してください</option>';

    if (workItems) {
      workItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          select.appendChild(option);
        });
    }
  }

  // 工数計算
  function calculateHours() {
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;

    if (!startTime || !endTime) {
      container.querySelector("#calculated-hours").textContent = "0時間 0分";
      return 0;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      container.querySelector("#calculated-hours").textContent = "0時間 0分";
      return 0;
    }

    let totalMinutes = Math.floor((end - start) / (1000 * 60));

    // 中断時間を差し引く
    const breakMinutes = currentBreaks.reduce((sum, br) => sum + (br.中断時間 || 0), 0);
    totalMinutes = Math.max(0, totalMinutes - breakMinutes);

    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;

    container.querySelector("#calculated-hours").textContent = `${hours}時間 ${minutes}分`;
    container.querySelector("#break-summary").textContent = `中断時間: ${breakMinutes}分`;

    return totalMinutes;
  }

  // 中断記録一覧を再描画
  function renderBreaks() {
    const tbody = container.querySelector("#break-list");
    tbody.innerHTML = currentBreaks.map((br, index) => `
      <tr>
        <td style="padding: 6px 10px; font-size: 13px;">${br.中断開始日時 ? new Date(br.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-'}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${br.中断終了日時 ? new Date(br.中断終了日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-'}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${br.中断理由区分 || '-'}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${br.中断時間 || 0}分</td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary delete-break-btn" data-index="${index}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">削除</button>
        </td>
      </tr>
    `).join("");

    calculateHours();
  }

  // 初期化
  loadCurrentUser();
  loadWorkItems();

  // 今日の日付をデフォルト設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#work-date").value = today;

  // 時刻変更時の工数計算
  container.querySelector("#start-time").addEventListener("change", calculateHours);
  container.querySelector("#end-time").addEventListener("change", calculateHours);

  // 中断記録ボタン
  container.querySelector("#btn-break").addEventListener("click", () => {
    window.showScreen("scr-1778907238439");
  });

  // 中断記録削除
  container.addEventListener("click", (e) => {
    const deleteBtn = e.target.closest(".delete-break-btn");
    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      if (confirm("この中断記録を削除しますか？")) {
        currentBreaks.splice(index, 1);
        renderBreaks();
      }
    }
  });

  // 一時保存ボタン
  container.querySelector("#btn-temp-save").addEventListener("click", async () => {
    const workData = {
      作業員ID: currentUser?.ユーザーID,
      作業日: container.querySelector("#work-date").value,
      作業開始時刻: container.querySelector("#work-date").value + "T" + container.querySelector("#start-time").value,
      作業終了時刻: container.querySelector("#end-time").value ? container.querySelector("#work-date").value + "T" + container.querySelector("#end-time").value : null,
      作業時間: calculateHours(),
      プロジェクト名: "一般作業",
      作業場所: container.querySelector("#work-location").value,
      作業種別: container.querySelector("#work-item option:checked")?.textContent?.split(" - ")[1] || "",
      作業内容: container.querySelector("#work-content").value,
      進捗状況: "作業中",
      備考: "",
      承認状態: "未承認",
      作成者ID: currentUser?.ユーザーID
    };

    const saved = await window.aivicApi.save(1, workData);
    if (saved) {
      alert("一時保存しました");
    }
  });

  // 記録確定ボタン
  container.querySelector("#btn-save").addEventListener("click", async () => {
    const workDate = container.querySelector("#work-date").value;
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const workLocation = container.querySelector("#work-location").value;
    const workContent = container.querySelector("#work-content").value;

    if (!workDate || !startTime || !endTime || !workLocation || !workContent) {
      alert("必須項目を入力してください");
      return;
    }

    const workData = {
      作業員ID: currentUser?.ユーザーID,
      作業日: workDate,
      作業開始時刻: workDate + "T" + startTime,
      作業終了時刻: workDate + "T" + endTime,
      作業時間: calculateHours(),
      プロジェクト名: "一般作業",
      作業場所: workLocation,
      作業種別: container.querySelector("#work-item option:checked")?.textContent?.split(" - ")[1] || "",
      作業内容: workContent,
      進捗状況: "完了",
      備考: "",
      承認状態: "未承認",
      作成者ID: currentUser?.ユーザーID
    };

    const saved = await window.aivicApi.save(1, workData);
    if (saved) {
      // 中断記録も保存
      for (const breakRecord of currentBreaks) {
        breakRecord.作業記録ID = saved.作業記録ID;
        await window.aivicApi.save(2, breakRecord);
      }

      alert("工数記録を確定しました");
      window.showScreen("scr-1778907226171");
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("入力内容を破棄して戻りますか？")) {
      window.showScreen("scr-1778907133295");
    }
  });

  // 初期描画
  renderBreaks();
}
